window.__SUM[20]={"LR000006":{"pair":"ADAM12 -> SDC4","headline":"The ADAM12 cysteine-rich domain supports cell attachment through syndecan-4 and triggers beta1-integrin-dependent spreading.","interaction_type":"functional only","direction_and_effect":"rADAM12-cys supports cell attachment using syndecan-4 as a primary receptor, which then triggers beta(1) integrin-dependent spreading, stress fibres and focal adhesions via PKC-alpha and RhoA [PMID:12509413].","molecular_requirements":"Syndecan-2 could not replace syndecan-4, and a mutant syndecan-4 deficient in PKC-alpha activation failed to promote spreading; downstream beta1 integrin needed [PMID:12509413].","affinity_potency":[],"species_and_systems":"Human proteins recorded; recombinant ADAM12 cysteine-rich domain in cell assays including Chinese hamster ovary beta1 cells [PMID:12509413].","localisation_and_range":"ADAM12 is flagged secreted [flag]; the ligand here is a recombinant domain, not full-length membrane ADAM12.","caveats":"One paper, abstract only; the ligand is the isolated cysteine-rich domain; direct binding constants are not reported.","key_references":[{"PMID":"12509413","why":"ADAM12 cysteine-rich domain acts through syndecan-4"}],"covers":["LR000006","LR003556"]},"LR000015":{"pair":"ADAM28 -> ITGA4","headline":"ADAM28 disintegrin domain is recognised by integrin alpha4beta1 on human lymphocyte lines; abstract only.","interaction_type":"functional only","direction_and_effect":"Jurkat adhesion to the MDC-L (ADAM 28) disintegrin domain was inhibited by anti-alpha4 and anti-beta1 mAbs, and alpha4beta1-transfected K562 cells adhered while untransfected did not [PMID:11724793].","molecular_requirements":"Both alpha4 and beta1 are implicated; adhesion correlated with alpha4 expression across cell lines [PMID:11724793].","affinity_potency":[],"species_and_systems":"Human; Jurkat T-lymphoma and K562 transfectants with recombinant Fc fusions [PMID:11724793].","localisation_and_range":"ADAM28 is flagged secreted [flag], but the paper says MDC-L is expressed on the surface of human lymphocytes [PMID:11724793].","caveats":"Abstract read only; adhesion assays.","key_references":[{"PMID":"11724793","why":"ADAM28 disintegrin is a ligand for alpha4beta1"}],"covers":["LR000015","LR003565"]},"LR000024":{"pair":"ADAM9 -> ITGB1","headline":"ADAM9 disintegrin domain binds beta1 integrins (alpha6beta1 shown); two abstract-only papers, human and mouse reagents.","interaction_type":"direct binding","direction_and_effect":"Murine meltrin gamma (ADAM9)-Fc bound integrin alpha6beta1 on HT1080 and Wehi 164 fibroblast lines in solid-phase and antibody-inhibition assays; cells on it showed rounded morphology and eight- to tenfold higher motility than on laminin, reduced by ROCK inhibitor Y-27632 [PMID:10825303]. Disintegrin domain capture of beta1 and other chains from renal lysate [PMID:15361064]. Curated effect: Stimulatory [flag].","molecular_requirements":"alpha6 partner shown for beta1 [PMID:10825303]; other beta1 integrins (alpha3, alphav) captured as chains [PMID:15361064]. The disintegrin domain is sufficient [PMID:15361064].","affinity_potency":[],"species_and_systems":"Mouse ADAM9-Fc on human cell lines [PMID:10825303]; human HEK-293 and renal lysate [PMID:15361064]. Mouse pair in the dossier is ortholog-inferred.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Both read as abstracts only. ITGB1 alone is a shared chain, so the pair is broad across alpha partners. Affinity not reported.","key_references":[{"PMID":"10825303","why":"meltrin gamma-Fc binds alpha6beta1 and drives motility"},{"PMID":"15361064","why":"disintegrin domain recovers beta1 and other chains"}],"covers":["LR000024","LR003574"]},"LR000033":{"pair":"ADM2 -> RAMP1","headline":"ADM2 binds the RAMP1-CLR extracellular complex (crystal structure); RAMP1 acts with CLR, not alone.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound the purified RAMP1-CLR ECD complex, and a 2.05 \u00c5 crystal structure with an antagonist fragment showed a triple beta-turn conformation, confirmed by mutagenesis [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. A PDB structure is recorded [DB:PDB 6D1U].","molecular_requirements":"RAMP1 together with CLR; AM2/IMD bound all three RAMP-CLR ECD complexes, preferring the RAMP1 (CGRP) and RAMP3 (AM2) complexes [PMID:30139742]. A bound fragment was an antagonist, not the full agonist peptide.","affinity_potency":[],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP1 is flagged receptor [flag]; ADM2 flagged secreted [flag].","caveats":"Abstract-only. The structure used an antagonist fragment. Agonism evidence is only the GtoPdb record. Review-only and abstract_insufficient papers not shown.","key_references":[{"PMID":"30139742","why":"crystal structure and binding of AM2/IMD to RAMP-CLR ECD"}],"covers":["LR000033","LR003583"]},"LR000042":{"pair":"AGRP -> MC4R","headline":"AGRP is a well-supported MC4R antagonist with binding, functional and structural abstract-level evidence and domain mapping.","interaction_type":"direct binding","direction_and_effect":"Recombinant AGRP was a potent, selective antagonist of Mc3r and Mc4r [PMID:9311920]; ART (AGRP) is an antagonist of human MC-3 and MC-4 receptors in functional assay [PMID:9299416]. GtoPdb lists an antagonist interaction with pIC50 units [DB:GtoPdb]. UniProt says the antagonist AGRP precludes agonist-induced signalling [DB:UniProt].","molecular_requirements":"Exoloops 2 and 3 of MC4R are needed for AGRP(87-132) binding, as substituting them with MC1R loops cut affinity and inhibitory activity [PMID:10318826] [PMID:12815165]. The AGRP 110-117 fragment instead depends on transmembrane domains 3 and 4 [PMID:12815165]. The RFF111-113 triplet and the Cys-110 to Cys-117 loop are critical for antagonism [PMID:9893984].","affinity_potency":[{"value":"pIC50 9.3","assay":"inhibition of radiolabeled alpha-MSH analog binding; functional antagonism","system":"human MC-4 receptor (companion MC-3 row, same paper)","cite":"PMID:9299416"}],"species_and_systems":"Human AGRP fragments and recombinant protein on human receptors or chimeras, mostly heterologous cells; transgenic mice for in vivo obesity [PMID:9311920] [PMID:12815165].","localisation_and_range":"AGRP is flagged secreted and non-transmembrane [flag].","caveats":"All six papers read as abstracts. The NMR structure is of the ligand alone [PMID:11747427]. The pIC50 9.3 comes from a row that the curator tied to MC3R and MC4R together. The pIC50 value is the dossier's affinity field and is not itemised per receptor in the abstract.","key_references":[{"PMID":"9299416","why":"Human ART/AGRP antagonises MC-3 and MC-4 receptors; pIC50 9.3"},{"PMID":"9311920","why":"Selective Mc3r/Mc4r antagonist, transgenic obesity"},{"PMID":"12815165","why":"Maps MC4R exoloop and transmembrane determinants of AGRP binding"}],"covers":["LR000042","LR003592"]},"LR000051":{"pair":"AMH -> AMHR2","headline":"AMH binds AMHR2 directly: a 2.6 A crystal structure plus binding and signalling data; the best-supported AMH receptor pair here.","interaction_type":"direct binding","direction_and_effect":"AMH binds and activates AMHR2, its dedicated type II receptor, as an agonist [PMID:34155118]. Cloned rabbit AMHR2 (longer 569-amino acid isoform) binds AMH when expressed in COS cells [PMID:7997230]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"X-ray structure of AMH bound to the AMHR2 extracellular domain at 2.6 A shows one AMHR2 contacting one AMH chain, with AMH dimerised via disulfide at C525 [PMID:34155118]. A finger-1 conformation and a K534 (AMH) salt bridge with D81/E84 (AMHR2) are key in a luciferase assay [PMID:34155118]. The longer isoform, not the shorter, binds AMH [PMID:7997230]. Type I partners are not defined in these papers.","affinity_potency":[],"species_and_systems":"Human proteins for the structure [PMID:34155118]; rabbit cDNA expressed in COS cells [PMID:7997230]. The mouse pair is inferred by orthology.","localisation_and_range":"AMH is flagged secreted [flag]; Reactome has AMH dimer:AMHR2 at the plasma membrane [DB:Reactome].","caveats":"[PMID:34155118] and [PMID:7997230] were read at abstract level by the curator; no affinity values in our evidence. One row pending, one review_only. IntAct records ELISA, pull-down and crystallography [DB:IntAct].","key_references":[{"PMID":"34155118","why":"Crystal structure of AMH-AMHR2 and key interface residues"},{"PMID":"7997230","why":"Cloning of AMHR2 and AMH binding in COS cells"}],"covers":["LR000051","LR003601"]},"LR002103":{"pair":"ANGPT2 -> ITGB1","headline":"Ang2 binds the beta1-integrin subunit in ELISA and activates beta1-integrin; supported by a full-text paper and an abstract-only glioma paper.","interaction_type":"direct binding","direction_and_effect":"Ang2, but not Ang1, activates beta1-integrin, leading to endothelial destabilization; this occurs independently of Tie2 [PMID:25635707]. Ang2 also interacts with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, ERK1/2 and JNK [PMID:16424009]. Agonist at the integrin.","molecular_requirements":"Ang2 directly bound the beta1-integrin subunit in ELISA; the Ang2 superclustering and coiled-coil domains were needed for activation (an Ang2-Ang1 chimera activated beta1-integrin like Ang2, the Ang1-Ang2 chimera did not) [PMID:25635707]. The glioma pathway needed both beta1 and alpha(v) integrins [PMID:16424009].","affinity_potency":[],"species_and_systems":"Endothelial cells, CHO and HeLa cells, ELISA, and Ang2 transgenic mice [PMID:25635707]; human glioma cells and murine xenografts [PMID:16424009]. BioGRID has reconstituted complex and affinity capture records [DB:BioGRID].","localisation_and_range":"ANGPT2 is flagged as secreted and ITGB1 as a receptor and not secreted [flag]; Ang2 localised to cell-matrix adhesions in HeLa cells [PMID:25635707].","caveats":"The ELISA shows binding to the beta1 subunit alone with no affinity value in our evidence. The glioma paper was read as an abstract and concerns the alphaVbeta1 heterodimer. Ang1 does not activate beta1-integrin [PMID:25635707]. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"25635707","why":"Direct ELISA binding of Ang2 to beta1-integrin; activation requires Ang2 not Ang1"},{"PMID":"16424009","why":"Ang2/alphaVbeta1 signalling in Tie2-deficient glioma cells"}],"covers":["LR002103","LR005429"]},"LR002112":{"pair":"ANGPTL4 -> CLDN5","headline":"cANGPTL4 is reported to bind claudin-5 and decluster it; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 subsequently associates with and declusters claudin-5 after activating integrin \u03b15\u03b21, leading to endothelial disruption; curator labels it antagonist [PMID:21841165]. ANGPTL4-knockout versus wild-type mice show it induces vascular leakiness and lung metastasis [PMID:21841165].","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Claudin-5 engagement comes after integrin \u03b15\u03b21 and alongside VE-cadherin [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; mice used in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 is flagged secreted [flag]; claudin-5 is an endothelial tight-junction protein (location taken from paper text on junction declustering) [PMID:21841165].","caveats":"Single paper read as abstract only; no affinity; CLDN5 is not flagged transmembrane in our entity record; fragment, not full-length.","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds claudin-5 as third sequential partner"}],"covers":["LR002112","LR005434"]},"LR002121":{"pair":"ANGPTL4 -> SDC4","headline":"Direct ANGPTL4-SDC4 binding is shown by cell-surface binding assay and ELISA, with Wnt-antagonist consequences.","interaction_type":"direct binding","direction_and_effect":"Soluble ANGPTL4 binds all four syndecans (SDC1-4) in cell-surface binding assays, and AP-tagged soluble SDC4 binds immobilised ANGPTL4 dose-dependently in ELISA [PMID:29017031]. The complex is internalised by clathrin-mediated endocytosis, promotes LRP6-SDC4 clustering and LRP6 turnover, and attenuates Wnt/\u03b2-catenin signalling [PMID:29017031].","molecular_requirements":"nANGPTL4 increased LRP6-SDC4 clusters while cANGPTL4 had no effect; chlorate sensitivity suggests syndecan binding is required for clustering [PMID:29017031].","affinity_potency":[],"species_and_systems":"Human ANGPTL4 and human SDC4 constructs in HEK293T cells; Xenopus embryos for function [PMID:29017031]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; SDC4 is a membrane receptor [flag]; binds on the cell surface.","caveats":"No affinity number in our excerpts; Wnt antagonism is shown through LRP6, not a classical receptor activation.","key_references":[{"PMID":"29017031","why":"ANGPTL4 binds syndecans, including SDC4, and promotes LRP6 turnover"}],"covers":["LR002121","LR005443"]},"LR002130":{"pair":"APLP1 -> CNTN4","headline":"APLP1 binds CNTN4 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN4; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. APLP1 appeared to interact more strongly with CNTN4 than with CNTN3 or CNTN5 [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002130","LR005447"]},"LR008697":{"pair":"APOB -> CALCR","headline":"Only BioGRID records from one paper; four papers were about a different entity, so evidence is doubtful.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-western and co-fractionation for APOB and CALCR from PMID 12397072 [DB:BioGRID]. Effect not reported in our evidence.","molecular_requirements":"CALCR is annotated as 'AMY1 receptor'; subunit requirements not reported in our evidence [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"CALCR carries transmembrane and receptor flags [flag].","caveats":"Judged rows: four different_entity and one review_only, none confirmed.","key_references":[],"covers":["LR008697"]},"LR012021":{"pair":"BAMBI -> ACVR2A:BMPR1B","headline":"BAMBI to ACVR2A:BMPR1B has no verified paper; support is one BioGRID reconstituted-complex record for BMPR1B only.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR2A and BMPR1B; the BioGRID record concerns BMPR1B only, one member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012021"]},"LR000105":{"pair":"BMP10 -> ACVR2B","headline":"Binding to the type II receptor ACVR2B is supported by one abstract-level binding study plus database records; no affinity in our evidence.","interaction_type":"direct binding","direction_and_effect":"BMP10 is annotated as stimulatory; GtoPdb lists it as an agonist at ACVR2B [DB:GtoPdb]. A kinetic and thermodynamic binding study reports that BMP9 discriminates among the type II receptors whereas BMP10 does not, which curators read as BMP10 binding ACVR2B (ActRIIB) [PMID:22718755]. BioGRID has a reconstituted-complex record for ACVR2B-BMP10 [DB:BioGRID].","molecular_requirements":"ACVR2B is a type II receptor; whether it needs a type I partner is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"Recombinant protein binding; curators annotate human ligand and receptor. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Support is indirect (BMP10 'does not discriminate' among type II receptors) and read from the abstract only; no Kd for ACVR2B is given in our evidence. outcome_counts lists two confirmed rows but only one paper is shown.","key_references":[{"PMID":"22718755","why":"Binding analysis of BMP9/BMP10 with ALK1 and type II receptors"}],"covers":["LR000105","LR003654"]},"LR000114":{"pair":"BMP15 -> BMPR1B","headline":"Supported by binding evidence in two papers: BMP15 binds BMPR1B (ALK6) in granulosa cells and COS cells.","interaction_type":"direct binding","direction_and_effect":"BMP15 activates Smad1/5/8 signalling in granulosa cells [PMID:12419820]. A radiolabelled covalent-dimer BMP15 variant bound preferentially to endogenous BMPR1B and BMPR2 on COV434 cells, confirmed in COS cells overexpressing them [PMID:22294741].","molecular_requirements":"BMPR1B (ALK6) ectodomain co-immunoprecipitated BMP15 most effectively among receptor ectodomains tested [PMID:12419820]. BMPR2 was bound alongside BMPR1B, forming a signalling complex [PMID:22294741].","affinity_potency":[],"species_and_systems":"Rat primary granulosa cells and human COV434 cells with recombinant ectodomains [PMID:12419820]; recombinant human BMP15 in COV434 and COS cells [PMID:22294741]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP15 is annotated as secreted [flag]; the 2012 abstract calls it oocyte-derived and acting on ovarian somatic cells in a paracrine manner [PMID:22294741].","caveats":"Both papers are abstract-only. Only the engineered covalent-dimer variant (S356C) kept receptor binding after iodination, not the natural noncovalent dimer [PMID:22294741]. No Kd in our evidence.","key_references":[{"PMID":"22294741","why":"Radioligand binding of BMP15 variant to BMPR1B/BMPR2"},{"PMID":"12419820","why":"ALK6 ectodomain co-IPs BMP15 in granulosa cells"}],"covers":["LR000114","LR003663"]},"LR000123":{"pair":"BMP2 -> HJV","headline":"HJV (RGMc) binds BMP-2 directly in biochemical and SPR assays; well supported as a BMP co-receptor.","interaction_type":"direct binding","direction_and_effect":"BMP-2 interacts with single-chain RGMc species and binds cell-associated RGMc [PMID:18287331]. RGMs are described as co-receptors enhancing BMP cellular responses [PMID:23029472].","molecular_requirements":"Single-chain RGMc species bind BMP-2; mutants linked to juvenile hemochromatosis bind less (D165E, G313V) or not at all (G92V) in mouse RGMc [PMID:18287331]. Neogenin preferentially binds membrane-associated heterodimeric RGMc, unlike BMP-2 [PMID:18287331].","affinity_potency":[{"value":"Kd 9.4 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"Mouse RGMc (human equivalents noted) for mutant binding [PMID:18287331]; SPR in a separate study [PMID:23029472]. Dossier covers the human pair and a projected mouse pair. PDB 4UI1 holds a structure with BMP2 and HJV chains [DB:PDB 4UI1].","localisation_and_range":"HJV is flagged secreted and receptor [flag]; it exists as membrane-linked and secreted isoforms [PMID:18287331].","caveats":"Both papers were read as abstract only (with limited excerpts). The Kd comes from the curator's assay note.","key_references":[{"PMID":"23029472","why":"SPR Kd for BMP2 binding to HJV"},{"PMID":"18287331","why":"BMP-2 binds RGMc species; mutants"}],"covers":["LR000123","LR003672"]},"LR000132":{"pair":"BMP5 -> HJV","headline":"BMP5 binds HJV in SPR with Kd 17 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"HJV is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. HJV showed the highest affinity among RGMs for BMP5, BMP6 and BMP7 [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 17 nM","assay":"SPR","system":"HJV vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. HJV is flagged secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR000132","LR003681"]},"LR000141":{"pair":"BMP7 -> ACVR2B","headline":"BMP7 binds ACVR2B (ActR-IIB) directly; SPR affinity in the same range as for ACVR2A, plus cell-based evidence.","interaction_type":"direct binding","direction_and_effect":"BMP7 binds the type II receptor ActR-IIB with comparable affinity to ActR-II and BMPR-IB [PMID:19735544]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"ACVR2B is a type II chain; BMP7 also binds type I receptors, with comparable affinities in vitro [PMID:19735544]. Whether ACVR2B alone is sufficient for signalling is not reported in our evidence.","affinity_potency":[{"value":"KD(eq) 9.2 nM","assay":"SPR, immobilised ActR-IIB ECD, soluble BMP7","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Recombinant human ligand and receptor ectodomains in SPR [PMID:19735544]. The dossier includes human and mouse pairs, neither ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Only one paper is shown in detail and it is a binding screen of multiple receptors; four confirmed rows were counted overall.","key_references":[{"PMID":"19735544","why":"SPR binding parameters for BMP7 with ActR-IIB"}],"covers":["LR000141","LR003690"]},"LR011202":{"pair":"BMP8B -> BMPR1B","headline":"BMP8B -> BMPR1B rests only on a GtoPdb agonist record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-BMPR1B as Type=Agonist, Action=Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"Single type I chain; need for a type II partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Receptor flagged as a receptor [flag]; range not reported in our evidence.","caveats":"No verified paper; three candidate papers were judged abstract-insufficient. The GtoPdb record is a database assertion only.","key_references":[],"covers":["LR011202"]},"LR000150":{"pair":"BTLA -> TNFRSF14","headline":"Well supported direct binding between BTLA and HVEM (TNFRSF14), with a structure and inhibitory signalling; papers describe HVEM as the ligand acting on BTLA.","interaction_type":"direct binding","direction_and_effect":"Binding competition and mutagenesis place the BTLA site on HVEM cysteine-rich domain 1 [PMID:16131544]. BTLA did not bind B7x and HVEM was identified as the unique BTLA ligand; HVEM engagement induced BTLA tyrosine phosphorylation and SHP-2 association and repressed T cell proliferation [PMID:15568026]. In mouse, HVEM engaging BTLA on T cells reduced TCR signalling and CD40L mobilisation, restraining germinal centre B cell participation [PMID:31204070]. The effect is inhibitory.","molecular_requirements":"The BTLA site is on HVEM CRD1, distinct from the LIGHT site [PMID:16131544, PMID:15568026]. A BTLA-HVEM complex structure exists [DB:PDB 2AW2]. No further subunit requirements reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant/cell binding work [PMID:16131544, PMID:15568026]; mouse in vivo B cell/T cell work [PMID:31204070]. Both entries are mouse and human, not inferred.","localisation_and_range":"Both partners are annotated as transmembrane [flag]. UniProt notes BTLA may interact in cis or in trans [DB:UniProt].","caveats":"The two binding papers were read as abstracts only. Herpesvirus gD blocks both BTLA and LIGHT binding to HVEM, and the CMV UL144 mimic binds BTLA [PMID:16131544]. No affinity values reported in our evidence.","key_references":[{"PMID":"15568026","why":"identifies HVEM as the BTLA partner, binds CRD1, SHP-2 signalling"},{"PMID":"16131544","why":"BTLA binding site mapped on HVEM CRD1 by competition and mutagenesis"},{"PMID":"31204070","why":"mouse in vivo: HVEM signals via BTLA on T cells"}],"covers":["LR000150","LR003699"]},"LR002220":{"pair":"C1QTNF5 -> ADIPOR1","headline":"Conflicting: CTRP5 relaxes vessels, a paper excerpt describes AdipoR-independent action, and UniProt describes CTRP5 as an ADIPOR1 antagonist.","interaction_type":"conflicting","direction_and_effect":"CTRP5 caused vasorelaxation comparable to adiponectin [PMID:21836066]. UniProt states CTRP5 antagonises ADIPOR1 and negatively regulates ADIPOR1-dependent AMPK activation in retinal pigment epithelium [DB:UniProt, PMID:34887495]. The ADIPOR1 mechanism in the vasorelaxation paper was tested for CTRP9 only.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Aortic vascular rings (murine CTRPs) and human umbilical vein endothelial cells (HUVECs) [PMID:21836066]. The ADIPOR1 knockdown was done with CTRP9. The excerpt notes, citing earlier work, that CTRP5's metabolic effect is AdipoR-independent (background, not this paper's result).","localisation_and_range":"Secreted ligand [flag]; range not reported.","caveats":"Direction conflicts (vasorelaxant agonist-like effect versus UniProt antagonist). No direct binding data in our evidence. Mouse interaction ortholog-inferred.","key_references":[{"PMID":"21836066","why":"CTRP5 vasorelaxation; ADIPOR1 mechanism tested for CTRP9"}],"covers":["LR002220","LR005533"]},"LR008949":{"pair":"CAMP -> P2RX7","headline":"LL-37 acts through P2X7 in two cell studies, as a modulator rather than a classical agonist.","interaction_type":"functional only","direction_and_effect":"LL-37 induced proliferation, Ca(2+) influx and ethidium bromide uptake in P2X7-expressing HEK293 cells, synergized with benzoyl ATP, and was blocked by KN-62 and absent in cells lacking P2X7 [PMID:18765670]. GtoPdb classes it as a positive allosteric modulator [DB:GtoPdb]. In SW620 colon cancer cells LL-37 inhibited migration through P2RX7 [PMID:30847383].","molecular_requirements":"Structural requirements: helix-forming propensity in aqueous solution was needed, not helix sense (the all-d analog was active) [PMID:18765670]. A truncated P2X7 unable to form the typical pore still gave pore activity [PMID:18765670].","affinity_potency":[],"species_and_systems":"Human fibroblasts and HEK293 cells [PMID:18765670]; human SW620 and HT-29 cells and nude mice [PMID:30847383]. The first paper is abstract-only, the second full text.","localisation_and_range":"CAMP is flagged secreted [flag]; paracrine action is implied by treatment of cells with peptide, not stated.","caveats":"Evidence is pharmacological (antagonist, knockdown), not direct binding. Effects differ in direction between papers (proliferation versus migration inhibition). One further paper was abstract_insufficient. P2X7's usual agonist is ATP in the curator note, and GtoPdb calls LL-37 an allosteric modulator, so effect type is uncertain.","key_references":[{"PMID":"18765670","why":"LL-37 proliferation and Ca2+ influx need P2X7"},{"PMID":"30847383","why":"LL-37 inhibition of migration is P2RX7-dependent"}],"covers":["LR008949"]},"LR000204":{"pair":"CCL16 -> HRH4","headline":"CCL16 binds the histamine H4 receptor with Kd 17 nM and acts as an agonist in vitro and in mice; a single paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: CCL16 induced pertussis toxin-sensitive calcium mobilisation and chemotaxis in L1.2 cells expressing H4 but not H1 or H2; injected intravenously it mobilised eosinophils from bone marrow, suppressed by thioperamide [PMID:15265943]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 17 nM","assay":"binding","system":"L1.2 cells expressing H4","cite":"PMID:15265943"}],"species_and_systems":"Human CCL16 on murine L1.2 transfectants; human and mouse eosinophils; mice in vivo; abstract-only [PMID:15265943].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single paper, abstract-only; H4 is outside the chemokine receptor family, so replication is worth checking.","key_references":[{"PMID":"15265943","why":"CCL16 as a histamine H4 receptor ligand"}],"covers":["LR000204"]},"LR000240":{"pair":"CCL2 -> ACKR1","headline":"Direct but non-signalling binding of CCL2 to ACKR1/DARC from two papers; scavenger-type atypical receptor.","interaction_type":"direct binding","direction_and_effect":"DARC bound CCL2 in competition binding, but DARC-bound CCL2 failed to induce a significant cytosolic calcium rise in CCR2B-expressing cells; DARC knockout mice showed no change in lymph node leukocyte composition or lymphocyte migration [PMID:13679391].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 34.9 nM","assay":"125I-CXCL8 displacement on erythrocytes","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor in binding [PMID:13679391][PMID:15358176]; knockout data are from mice [PMID:13679391]. A mouse interaction record also exists.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Binds selected inflammatory but not homeostatic chemokines [PMID:15358176]. The affinity is taken from a curator note for a displacement table row; which chemokine row it covers is not stated in the abstract. Effect described as neutral, not signalling [PMID:13679391]. BioGRID records a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"13679391","why":"DARC binds CCL2 but not lymphoid chemokines; non-signalling"},{"PMID":"15358176","why":"Duffy antigen displacement binding, Ki 34.9 nM"}],"covers":["LR000240","LR003761"]},"LR000213":{"pair":"CCL20 -> CCR6","headline":"Well supported direct CCL20-CCR6 binding and agonism, shown in several human transfected-cell studies; mouse pair is projected from human.","interaction_type":"direct binding","direction_and_effect":"CCL20 (LARC/MIP-3alpha) acts as an agonist at CCR6: it induced calcium flux and migration in CCR6-expressing cells [PMID:9169459] and calcium flux in STRL22 (CCR6)-transfected HEK293 cells [PMID:9223454]. Activation was pertussis-toxin-sensitive and phospholipase C-dependent in HEK 293 cells [PMID:9294137]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR6 alone was sufficient in transfected cells; no co-receptor or extra subunit is reported in our evidence. CCL20 binding to CCR6 was specific: five other CC chemokines did not compete [PMID:9169459]. A PDB structure of the two chains exists [DB:PDB 6WWZ].","affinity_potency":[{"value":"Kd 0.9 nM","assay":"LARC-SEAP binding to CCR6 (GPR-CY4)-expressing cells","system":"Raji cells stably expressing human CCR6","cite":"PMID:9169459"},{"value":"pIC50 7.9-8.5","assay":"GtoPdb affinity range (assay not given in our evidence)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments were on human ligand and human receptor in recombinant cells (HEK293, Raji, K562) and CCR6 cloned from lung dendritic cells [PMID:9169459][PMID:9223454][PMID:9294137]. The mouse pair is inferred from human, with no mouse experiment in the dossier.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Most papers were read as abstracts only. PMID:12081481 treats CCL20-CCR6 as background and is a receptor cysteine-mutagenesis study, so it supports the pair only indirectly. PMID:10521347 concerns beta-defensin displacing iodinated CCL20 from CCR6, so it supports CCL20 binding only as a reference radioligand.","key_references":[{"PMID":"9169459","why":"Kd 0.9 nM binding and CCR6 identification"},{"PMID":"9223454","why":"independent specific binding and calcium flux"},{"PMID":"9294137","why":"CCR6 cloned as MIP-3alpha receptor; pertussis-toxin-sensitive calcium signalling"}],"covers":["LR000213","LR003740"]},"LR000222":{"pair":"CCL25 -> ACKR4","headline":"CCL25 binds ACKR4 with high affinity; ACKR4 acts mainly as an internalising decoy receptor.","interaction_type":"direct binding","direction_and_effect":"ACKR4 internalises CCL25 and acts as a decoy, preventing interaction with receptors such as CCR7 and CCR9 [PMID:23341447]. Beta-arrestin recruitment occurred with CCL19, CCL21 and CCL25 [PMID:23341447]; a 2021 screen lists CCL25 among ACKR4 agonists [PMID:32480426]. Effect is classed neutral for the curated binding row [PMID:23341447].","molecular_requirements":"Wild-type ACKR4 acts alone; its signalling needs an intact DRY motif and is seen in the presence of pertussis toxin [PMID:23341447].","affinity_potency":[{"value":"pKi 7.6","assay":"curated binding value","system":"ACKR4 (CCX-CKR) receptor","cite":"PMID:23341447"},{"value":"IC50 <15 nM","assay":"radioligand competition; TECK among high-affinity ligands","system":"cells expressing human CCX CKR","cite":"PMID:10706668"},{"value":"pEC50 7.9-8.3","assay":"GtoPdb agonist range","system":"database record","cite":"PMID:23341447"}],"species_and_systems":"Human ligand and receptor in cell lines [PMID:23341447][PMID:10706668][PMID:32480426].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Abstracts only. The 1999 paper tentatively called this receptor CCR10 [PMID:10706668]. Classic G-protein signalling is absent but latent signalling exists, so 'silent' is too simple [PMID:23341447].","key_references":[{"PMID":"10706668","why":"Identified CCX CKR and ranked its chemokine ligands"},{"PMID":"23341447","why":"Decoy and arrestin properties with CCL25"},{"PMID":"32480426","why":"Independent beta-arrestin screen of ACKR4 ligands"}],"covers":["LR000222"]},"LR000231":{"pair":"CCL28 -> CCR3","headline":"CCL28 supports migration through CCR3 in one abstract-read paper (human); GtoPdb lists it as an agonist. Thinly supported.","interaction_type":"functional only","direction_and_effect":"CCL28 supports migration through CCR3 as well as CCR10 and attracts eosinophils [PMID:10975800]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins [PMID:10975800]. The mouse pair is ortholog-inferred from human.","localisation_and_range":"CCL28 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"Only one paper, read as abstract only, with a functional readout; no direct binding or affinity in our evidence. The mouse pair has no mouse experiment.","key_references":[{"PMID":"10975800","why":"CCL28 supports migration via CCR3 and attracts eosinophils"}],"covers":["LR000231","LR003752"]},"LR000420":{"pair":"CCN1 -> ITGAM","headline":"CCN1 supports monocyte adhesion through integrin alphaMbeta2; alphaM I-domain binding mapped to a CCN1 peptide. Chain-only (alphaM) evidence.","interaction_type":"direct binding","direction_and_effect":"THP-1 and peripheral blood monocytes adhered to Cyr61 (CCN1) mainly through alphaMbeta2, and a GST-alphaM I-domain bound immobilized Cyr61 [PMID:12036876]. Activated monocytes adhered to the CCN1 H2 peptide (SSVKKYRPKYCGS), blocked by anti-alphaM mAb 2LPM19c, and GST-alphaMI bound this peptide [PMID:12736251].","molecular_requirements":"The ITGAM chain pairs with beta2 as alphaMbeta2; heparan sulfate proteoglycans act as co-receptors, since heparin or heparinase I partly inhibited adhesion [PMID:12036876]. Adhesion was activation-dependent.","affinity_potency":[],"species_and_systems":"Human THP-1 cells, human monocytes, HEK293 cells expressing alphaMbeta2 and GST-fusion I-domain; human CCN1. Mouse and any other pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers were read as abstracts only. Evidence is adhesion and I-domain binding, with no affinity. The dossier's alphaM and beta2 entries describe the same alphaMbeta2 heterodimer evidence.","key_references":[{"PMID":"12036876","why":"alphaMbeta2 identified as monocyte adhesion receptor for CCN1"},{"PMID":"12736251","why":"alphaM binding site mapped to CCN1 H2 peptide"}],"covers":["LR000420","LR003917"]},"LR005100":{"pair":"CD96 -> PVR","headline":"CD96 binds CD155 (PVR) in mouse; human interaction ortholog-inferred, with PDB and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Mouse CD96/CD155 complexes form and are blocked by anti-mCD96 and anti-mCD155 antibodies; T-cell adhesion to mCD155 insect cells is blocked in a T-cell-subtype-dependent manner [PMID:17971293]. Reactome records CD96 binding PVR [DB:Reactome].","molecular_requirements":"Not reported beyond a single chain pair; PDB 6ARQ has a structure with one chain of each partner [DB:PDB 6ARQ].","affinity_potency":[],"species_and_systems":"Mouse thymocytes/T cells and insect cells; the paper states the interaction is preserved between man and mouse [PMID:17971293].","localisation_and_range":"Membrane proteins; adhesion between cells [PMID:17971293].","caveats":"Only one paper, abstract-only; the human pair rests on projection plus databases [DB:IntAct].","key_references":[{"PMID":"17971293","why":"CD96/CD155 adhesion, mouse"}],"covers":["LR001735","LR005100"]},"LR002301":{"pair":"CDH1 -> FGFR1","headline":"Curators verified absence: the paper concerns Cdh2 and FGFR1, not Cdh1; database co-IP records exist.","interaction_type":"conflicting","direction_and_effect":"Cdh2 co-immunoprecipitated with and stabilised FGFR1 in mouse epiblast stem cells; Cdh1 overexpression did not restore pluripotency gene expression [PMID:26420260].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse epiblast stem cells and ESCs [PMID:26420260]; human pair ortholog-inferred.","localisation_and_range":"Membrane proteins [flag].","caveats":"Two papers judged pair_absent. IntAct anti-bait co-IP and BioGRID reconstituted complex records are listed [DB:IntAct] [DB:BioGRID]; direct Cdh1 binding not shown.","key_references":[{"PMID":"26420260","why":"Cdh2, not Cdh1, interacts with FGFR1"}],"covers":["LR002301","LR005599"]},"LR002310":{"pair":"CDH2 -> CDH2","headline":"N-cadherin homophilic ligation signals through PI3K/Akt in human prostate carcinoma cells; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Homophilic N-cadherin ligation activated PI3K-dependent Akt and Bad Ser136 phosphorylation, with a 3.5-fold Bcl-2 increase and Bax unchanged [PMID:12095980]. E-cadherin ligation in the same cells did not activate Akt (curator note) [PMID:12095980].","molecular_requirements":"PI3K co-immunoprecipitated with the N-cadherin/catenin complex and recruitment required an intact actin cytoskeleton (blocked by cytochalasin D) [PMID:12095980].","affinity_potency":[],"species_and_systems":"Human PC3/PC3N prostate carcinoma cells, abstract only [PMID:12095980]. The mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound homophilic trans adhesion, contact-dependent [flag][PMID:12095980].","caveats":"Direct homophilic binding is not measured in our evidence; only cell responses. Ligand and receptor are the same molecule, so direction is a formality. Abstract-only.","key_references":[{"PMID":"12095980","why":"N-cadherin homophilic ligation activates PI3K/Akt"}],"covers":["LR002310","LR005608"]},"LR007959":{"pair":"CHL1 -> CHL1","headline":"Homophilic CHL1 interaction rests on a large SPR screen database record; the cited evidence sentence is generic.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported in our evidence; the pair is classed adhesion-adhesion (self-interaction) [flag]. IntAct records surface plasmon resonance for CHL1-CHL1 [DB:IntAct], citing the immune-system surface interaction map [PMID:35922511].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; the source paper used a recombinant library of leukocyte surface proteins [PMID:35922511].","localisation_and_range":"CHL1 is flagged secreted, receptor and transmembrane [flag]; adhesion contact interaction.","caveats":"The curator's evidence sentence is generic text about membrane-protein methods, not a CHL1 result. Pair support comes mainly from the IntAct SPR record. No affinity reported in our evidence.","key_references":[{"PMID":"35922511","why":"High-throughput surface receptor screen of the human immune system"}],"covers":["LR007959"]},"LR000303":{"pair":"CLCF1 -> IL6ST","headline":"IL6ST (gp130) is engaged only as a signalling chain of the CNTFR complex; evidence is functional activation, not direct binding.","interaction_type":"functional only","direction_and_effect":"The CLF/CLC complex activated gp130, LIFR and STAT3 and supported motor neuron survival [PMID:10966616]. CLC-CNTFR displayed activity on cells with gp130-LIFR [PMID:11285233]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"gp130 acts downstream of CNTFR: curator notes say it is a signalling chain engaged by the complex, not an independent CLC binding partner [PMID:11285233]. UniProt says binding to CNTFR induces gp130 heterodimerisation with LIFR [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-level evidence only [PMID:10966616][PMID:11285233].","localisation_and_range":"Ligand flagged secreted and IL6ST a transmembrane receptor [flag].","caveats":"Both papers abstract only. Direct CLCF1-IL6ST binding is not shown in our evidence; do not score this pair without CNTFR.","key_references":[{"PMID":"10966616","why":"gp130 and LIFR activation by CLF/CLC"},{"PMID":"11285233","why":"CLC-CNTFR activity on gp130-LIFR cells"}],"covers":["LR000303","LR003809"]},"LR000312":{"pair":"CNTN2 -> NRP1","headline":"TAG1 reported to interact with NRP1 in mouse sensory-neuron Sema3A receptor trafficking; abstract-only.","interaction_type":"direct binding","direction_and_effect":"TAG1 interacts with NRP1, changing its association with L1 so L1 is lost from the complex after Sema3A binding [PMID:22836270]. Without TAG1, NRP1 and L1 failed to separate and Plexin signalling was not initiated [PMID:22836270].","molecular_requirements":"Sema3A receptor complex contains NRP1 (ligand-binding subunit), PlexinA4 and L1 [PMID:22836270].","affinity_potency":[],"species_and_systems":"Mouse spinal sensory neuron growth cones [PMID:22836270]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Intracellular endosomal sorting and raft association in growth cones [PMID:22836270]; both partners carry secreted/receptor flags [flag].","caveats":"Abstract-only; interaction is described in a trafficking context, direct binding assay details are not in our evidence. TAG1 acts as a sorting regulator rather than classical ligand.","key_references":[{"PMID":"22836270","why":"TAG1 interacts with NRP1 in Sema3A trafficking"}],"covers":["LR000312","LR003818"]},"LR000321":{"pair":"COL18A1 -> KDR","headline":"Endostatin (collagen XVIII fragment) directly interacts with KDR and blocks VEGF signalling; one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Endostatin blocked VEGF-induced KDR/Flk-1 tyrosine phosphorylation and ERK, p38 and FAK activation in HUVEC, and inhibited VEGF165 binding to endothelial cells and purified KDR ectodomain and VEGF121 binding to KDR; direct interaction was confirmed by affinity chromatography [PMID:12029087]. Antagonist: endostatin did not bind VEGF, so the block is at the receptor [PMID:12029087].","molecular_requirements":"Ligand is endostatin, the C-terminal fragment of collagen XVIII, not full-length COL18A1 [PMID:12029087].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells and purified KDR ectodomain; abstract only [PMID:12029087]. BioGRID: reconstituted complex [DB:BioGRID, PMID:12029087].","localisation_and_range":"Ligand is a secreted fragment; receptor is a transmembrane kinase.","caveats":"Abstract-only read; no affinity reported; one paper, and the BioGRID record cites the same paper.","key_references":[{"PMID":"12029087","why":"Endostatin directly interacts with KDR/Flk-1 and blocks VEGF signalling"}],"covers":["LR000321","LR003827"]},"LR000330":{"pair":"COL1A2 -> CD44","headline":"Affinity-purified lymphocyte CD44 bound native type I collagen fibrils in one 1992 study.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound native type I collagen fibrils, laminin and fibronectin, but not gelatin [PMID:1730778]; effect not reported in our evidence.","molecular_requirements":"Not reported for collagen; fibronectin binding was via the chondroitin sulfate-containing CD44 form [PMID:1730778].","affinity_potency":[],"species_and_systems":"Human lymphocyte CD44 purified protein binding assay [PMID:1730778].","localisation_and_range":"CD44 is flagged secreted and transmembrane [flag]; collagen is matrix [flag].","caveats":"Single paper, focused on fibronectin. The collagen result is for type I collagen as a whole, not COL1A2 alone. No database support.","key_references":[{"PMID":"1730778","why":"Affinity-purified CD44 binds native type I collagen fibrils"}],"covers":["LR000330","LR003836"]},"LR002400":{"pair":"COL4A2 -> DDR2","headline":"Direct but weak collagen IV binding and phosphorylation of DDR2 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR2 and induced phosphorylation, weaker than fibril-forming collagens [PMID:9659900].","molecular_requirements":"No co-receptor requirement reported in our evidence. COL4A2 is inferred as a chain of the tested commercial type IV collagen, not tested alone [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot and phosphorylation assays; other species are projections [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002400","LR005679"]},"LR006969":{"pair":"COL6A1 -> ITGA1:ITGB1","headline":"Weak: one abstract reports COL6A1 binding ITGB1 in glioblastoma; the alpha subunit is not named.","interaction_type":"functional only","direction_and_effect":"COL6A1 is bound to ITGB1 on endothelial cells, disrupting tight junctions via UBD-mediated claudin-5 degradation [PMID:41297453].","molecular_requirements":"The paper names only ITGB1, not the alpha partner, so ITGA1:ITGB1 is not distinguished from other beta1 heterodimers [PMID:41297453].","affinity_potency":[],"species_and_systems":"Human patient-derived glioblastoma organoids and endothelial cells [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the binding wording is an abstract statement. No affinity reported. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"41297453","why":"COL6A1 binds endothelial ITGB1 in TMZ-resistant glioblastoma"}],"covers":["LR006969"]},"LR006996":{"pair":"COL8A1 -> ITGA2:ITGB1","headline":"COL8A1-ITGB1 interaction reported in colorectal and pancreatic cancer abstracts; the ITGA2 chain itself is not tested.","interaction_type":"functional only","direction_and_effect":"In colorectal cancer, COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance [PMID:39732719]. In PDAC cells, ITGB1 and DDR1 activation, PI3K/AKT and NF-\u03baB signaling occurred downstream of COL8A1 [PMID:36375776].","molecular_requirements":"Evidence names ITGB1 only; the ITGA2 subunit is not mentioned in our evidence, so the alpha-chain requirement is not reported. Full-text excerpts of PMID:39732719 describe CellChat COL8A1-ITGB1 inference, spatial colocalisation and molecular docking, not subunit requirements [PMID:39732719].","affinity_potency":[],"species_and_systems":"Human colorectal cancer and PDAC cells; both papers read as abstract, with excerpts for PMID:39732719.","localisation_and_range":"Ligand flagged secreted [flag]; CAF-to-tumor-cell paracrine/matrix signaling in the CRC study [PMID:39732719].","caveats":"Complex-level support rests on ITGB1 alone; part of the support is computational (CellChat, spatial colocalisation, docking). Four further rows are review-only.","key_references":[{"PMID":"39732719","why":"COL8A1 from CAFs interacts with ITGB1 in CRC"},{"PMID":"36375776","why":"COL8A1 activates ITGB1/DDR1 signaling in PDAC"}],"covers":["LR006996"]},"LR011211":{"pair":"CSF3 -> CSF2RB","headline":"No paper evidence that G-CSF engages CSF2RB; only a GtoPdb agonist entry.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CSF3-CSF2RB as agonist [DB:GtoPdb]; no paper shown supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Both judged rows were abstract_insufficient; none confirmed.","key_references":[],"covers":["LR011211"]},"LR011040":{"pair":"CTSG -> F2RL2","headline":"Cathepsin G disables human PAR3 rather than activating it; one abstract-read paper.","interaction_type":"functional only","direction_and_effect":"Cathepsin G and elastase prevented thrombin activation of phospholipase C in COS cells expressing human PAR3, so cathepsin G disarms PAR3 [PMID:11307827]. The interaction is annotated stimulatory, which this contradicts.","molecular_requirements":"The inhibition occurred without loss of binding sites for two monoclonal antibodies flanking the tethered ligand [PMID:11307827].","affinity_potency":[],"species_and_systems":"COS-7 cells with human PAR3 and mouse platelets [PMID:11307827].","localisation_and_range":"CTSG flagged secreted [flag]; protease acting on cell-surface receptor.","caveats":"Abstract only; effect is inhibitory, so the receptor is inactivated, not agonized. Cathepsin G did not aggregate murine platelets [PMID:11307827].","key_references":[{"PMID":"11307827","why":"Cathepsin G inactivates human PAR3"}],"covers":["LR011040"]},"LR000402":{"pair":"CXCL12 -> ITGB1","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrins alpha4beta1 and alpha5beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrins alpha4beta1 and alpha5beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGB1 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human. One further abstract_insufficient paper was judged.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR000402","LR003907"]},"LR000411":{"pair":"CXCL3 -> CXCR1","headline":"Weak support: functional ASMC migration data only, and curators recorded a verified negative that CXCR1 is IL-8-selective.","interaction_type":"conflicting","direction_and_effect":"CXCL3-induced ASMC migration depended on p38 and ERK1/2 MAPK via CXCR1 and CXCR2; in asthmatic cells migration was mainly PI3K-mediated through CXCR1 [PMID:23904157].","molecular_requirements":"Both CXCR1 and CXCR2 contributed in normal cells [PMID:23904157].","affinity_potency":[],"species_and_systems":"Human primary ASMCs [PMID:23904157]; HEK293 transfectants for binding papers [PMID:8702798].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"An abstract-read paper states IL-8RA (CXCR1) is selective only for IL-8 [PMID:8550564]. GRO-family chemokines competed only weakly at IL8RA [PMID:8702798]. All papers abstract-only; no affinity for this pair.","key_references":[{"PMID":"23904157","why":"CXCL3 migration via CXCR1 and CXCR2"},{"PMID":"8550564","why":"CXCR1 selective only for IL-8"},{"PMID":"8702798","why":"Weak competition at IL8RA"}],"covers":["LR000411"]},"LR000501":{"pair":"EFNA5 -> EPHA3","headline":"Ephrin-A5 is a well-established, high-affinity EphA3 ligand: Kd 12 nM, crystal structure and cell effects.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A5 (AL1/LERK7) is the preferred high-affinity ligand for HEK (EphA3), forming a stable 1:1 complex [PMID:9195962]. Ephrin-A5 stimulation of EphA3 inhibits 293A cell migration, reduces NG108-15 neurite outgrowth and collapses hippocampal growth cones [PMID:20697431]. Soluble ephrin-A5, ephrin-A2 and EphA3 extracellular domain abolished repulsive tectal activity in a stripe assay [PMID:9751130].","molecular_requirements":"1:1 complex stoichiometry [PMID:9195962]; the structure shows ephrin-A5 tilted on the EphA3 ligand-binding domain with extra contacts outside the canonical pocket [PMID:25993310]. Cytoplasmic Y602 and Y779 carry signalling [PMID:20697431].","affinity_potency":[{"value":"Kd 12 nM","assay":"surface plasmon resonance, size exclusion HPLC, sedimentation equilibrium (1:1 complex)","system":"HEK exodomain with ephrin-A5-Fc/FLAG fusions","cite":"PMID:9195962"}],"species_and_systems":"Human recombinant proteins and cells [PMID:9195962, PMID:25993310, PMID:20697431]; rat tectal axons [PMID:9751130]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ephrin-A5 flagged membrane-bound; EPHA3 flagged secreted and transmembrane [flag]; soluble forms were active in the stripe assay [PMID:9751130].","caveats":"Most papers were abstract-only reads; 22568954 (ELISA, high apparent affinity for most EphA receptors) was a browser read with an unverifiable quote.","key_references":[{"PMID":"9195962","why":"Kd 12 nM, 1:1 complex"},{"PMID":"25993310","why":"Crystal structure of EphA3 LBD with ephrin-A5"},{"PMID":"20697431","why":"Ephrin-A5 stimulation of EphA3 inhibits migration and neurite outgrowth"}],"covers":["LR000501","LR003992"]},"LR003999":{"pair":"EFNB1 -> EPHA4","headline":"No curator-verified paper; support is one IntAct surface plasmon resonance record.","interaction_type":"database-asserted only","direction_and_effect":"not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct SPR record from PMID 35922511; species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No confirmed papers: judged rows are review_only (6) and abstract_insufficient (4). Rests on a database record alone [DB:IntAct].","key_references":[],"covers":["LR000508","LR003999"]},"LR000510":{"pair":"EFNB1 -> EPHB2","headline":"Functional reverse-signalling evidence into ephrin-B1 cells on EphB2-Fc exposure; direct binding data absent from our evidence.","interaction_type":"functional only","direction_and_effect":"EphB2-Fc stimulation induced RhoA activation and enhanced motility and invasiveness of ephrinB1-expressing cells [PMID:29059157]. Clustered Nuk ectodomain induced tyrosine phosphorylation of the transmembrane ligands Elk-L or Htk-L [PMID:8878483]. So signalling runs into the ephrin-B1 cell (reverse).","molecular_requirements":"RhoGDI1 binds ephrinB1 (amino acids 327-334), and binding is enhanced by EphB2 extracellular domain [PMID:29059157].","affinity_potency":[],"species_and_systems":"Human cancer lines (SW480, Hs578T) were used for knockdown [PMID:29059157]; the other study used cells expressing the ligands and Nuk, species not specified [PMID:8878483]. UniProt says ephrin-B1 can also bind EPHB2 [DB:UniProt].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Both papers abstract-level; neither measures affinity. Elk-L/Htk-L naming and Nuk=EphB2 are curator mappings. IntAct solid phase record [DB:IntAct].","key_references":[{"PMID":"29059157","why":"EphB2-Fc drives ephrinB1/RhoGDI1/RhoA signalling"},{"PMID":"8878483","why":"Nuk ectodomain induces ligand tyrosine phosphorylation"}],"covers":["LR000510","LR004001"]},"LR004002":{"pair":"EFNB1 -> EPHB3","headline":"No verified paper; support is UniProt text and an IntAct co-immunoprecipitation.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ephrin-B1 can also bind EPHB2 and EPHB3 [DB:UniProt]; effect annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct association by anti-tag co-immunoprecipitation (PMID 33961781); species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Six judged papers were review_only; none confirmed. Rests on database records alone [DB:UniProt] [DB:IntAct].","key_references":[],"covers":["LR000511","LR004002"]},"LR004011":{"pair":"EFNB2 -> EPHB3","headline":"No verified paper; support is UniProt text and IntAct co-immunoprecipitations.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: forward and reverse signalling through the EFNB2/EPHB3 complex regulate migration and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct anti-tag co-immunoprecipitation records (PMIDs 28514442, 33961781); species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Six judged papers were review_only; none confirmed. Rests on database records alone.","key_references":[],"covers":["LR000520","LR004011"]},"LR005889":{"pair":"FGB -> CDH5","headline":"Fibrin(ogen) betaN-domains bind VE-cadherin domain 3 by ELISA and SPR; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The VE-cadherin-binding site is in the fibrin betaN-domains (N-terminal regions of beta chains); betaN-domains are the only fibrin(ogen) regions involved [PMID:19413351].","molecular_requirements":"The complementary site is the third extracellular VE-cadherin domain, unaffected by neighbouring domains; calcium does not influence binding [PMID:19413351].","affinity_potency":[],"species_and_systems":"Recombinant fragments; species not recorded in our evidence. Mouse pair is ortholog-inferred [PMID:19413351].","localisation_and_range":"FGB flagged secreted; CDH5 transmembrane [flag].","caveats":"Abstract only; no affinity in our evidence. Fibrin and fibrinogen are not distinguished beyond betaN-domains.","key_references":[{"PMID":"19413351","why":"betaN-domain binds VE-cadherin domain 3"}],"covers":["LR002623","LR005889"]},"LR008499":{"pair":"FGF13 -> SCN5A","headline":"FGF13 and SCN5A are linked by structural and interaction records, but this is not a classical secreted ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt notes the interaction is direct and FGF13 may regulate SCN5A density at membranes and function [DB:UniProt]; the pair is annotated as inhibitory in our records.","molecular_requirements":"A crystal structure contains the C-terminus of the sodium channel with FGF13 and calmodulin (CaM), so calmodulin is part of that complex [DB:PDB 4DCK].","affinity_potency":[],"species_and_systems":"Pull-down and co-immunoprecipitation records in IntAct [DB:IntAct]; the structure is X-ray diffraction [DB:PDB 4DCK]. Species of experiments not reported in our evidence.","localisation_and_range":"Not stated in our evidence; the entity flags were not provided.","caveats":"No curator-verified paper; the one judged paper was marked different_entity. The partner is an intracellular channel binding protein, so the 'ligand-receptor' framing is doubtful and should be used cautiously in CCC.","key_references":[{"PMID":"22705208","why":"crystal structure of channel C-terminus with FGF13 and CaM"}],"covers":["LR008499"]},"LR005898":{"pair":"FGF2 -> LYVE1","headline":"FGF2 binds LYVE-1 in several in vitro formats and LYVE-1 loss impairs FGF2 function; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"FGF2 binds LYVE-1 by AlphaScreen, on immobilised protein and in solution, and also when LYVE-1 is overexpressed in CHO cells. Soluble LYVE-1 or LYVE-1 knockdown impaired FGF2 signalling, and FGF2-induced (not VEGF-C-induced) lymphangiogenesis in vivo was inhibited [PMID:23264596].","molecular_requirements":"LYVE-1 glycosylation is important for FGF2 binding [PMID:23264596]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor recorded; CHO cells and lymphatic endothelial cells, with an in vivo lymphangiogenesis assay [PMID:23264596]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF2 is flagged secreted and LYVE-1 a receptor [flag]; LYVE-1 location is not otherwise described.","caveats":"Single paper read as abstract only; the abstract says FGF2 binds LYVE-1 with higher affinity than hyaluronan or PDGF-BB but gives no value. FGF2 also modulates LYVE-1 expression [PMID:23264596].","key_references":[{"PMID":"23264596","why":"FGF2 binds LYVE-1; LYVE-1 needed for FGF2 lymphangiogenesis"}],"covers":["LR002632","LR005898"]},"LR004101":{"pair":"FGF2 -> SDC3","headline":"Purified N-syndecan (SDC3) binds bFGF with Kd = 0.5 nM through its heparan sulfate chains; one older abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"N-syndecan purified from neonatal rat brain bound bFGF in a saturable solid-phase assay; soluble bFGF competed, showing solution-phase interaction. The authors suggest N-syndecan may act as a bFGF co-receptor [PMID:8344959]. BioGRID lists a reconstituted-complex record [DB:BioGRID].","molecular_requirements":"Heparin and heparan sulfate, not chondroitin sulfate, inhibited binding; the isolated core protein did not bind bFGF significantly, so HS chains are responsible [PMID:8344959]. Acidic FGF did not bind significantly [PMID:8344959].","affinity_potency":[{"value":"KD = 0.5 nM","assay":"solid-phase binding assay, N-syndecan with bFGF","system":"N-syndecan purified from neonatal rat brain","cite":"PMID:8344959"}],"species_and_systems":"Rat brain protein; the dossier records human for both partners, but the abstract describes neonatal rat brain [PMID:8344959]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Entity flags give no membrane annotation for SDC3 beyond receptor [flag]; N-syndecan is described as a cell-surface proteoglycan [PMID:8344959].","caveats":"Single paper, abstract only. Binding is mediated by HS chains rather than the core protein. Co-receptor role is a suggestion, not tested here.","key_references":[{"PMID":"8344959","why":"Purified N-syndecan binds bFGF, Kd 0.5 nM"}],"covers":["LR000617","LR004101"]},"LR000600":{"pair":"FGF21 -> FGFR2","headline":"Functional (mitogenic) activity of FGF21 on FGFR2c reported in one screen; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"FGF21 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but not FGFR1b, 2b or 3b in a BaF3 mitogenic assay [PMID:16597617]. Effect is stimulatory (activation) [PMID:16597617].","molecular_requirements":"Only the c splice forms were active; KLB involvement is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 cell lines expressing individual FGFRs; ligand and receptor species unspecified [PMID:16597617].","localisation_and_range":"Localisation not reported in our evidence beyond flags: FGF21 secreted [flag]; FGFR2 transmembrane [flag].","caveats":"Single paper, functional readout only, abstract-only reading of a browser-read quote that is unverified [PMID:16597617]. No direct binding data. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR000600","LR004084"]},"LR004110":{"pair":"FGF5 -> FGFR1","headline":"FGF5 binds and activates FGFR1 with nanomolar affinity in human recombinant studies; also supported by database records.","interaction_type":"direct binding","direction_and_effect":"Recombinant human FGF-5 bound and induced autophosphorylation of FGFR1 and FGFR2 (agonist) [PMID:8386828]. The BaF3 survey reports FGF5 activating c splice forms [PMID:8663044].","molecular_requirements":"Activity was shown in the presence of heparin [PMID:8386828]. UniProt lists FGF5 among in vitro interactors of FGFR1 [DB:UniProt]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[{"value":"KD between 0.5 and 1.5 x 10(-9) M","assay":"competition binding","system":"recombinant human FGF-5 with human FGFR-1","cite":"PMID:8386828"}],"species_and_systems":"Human recombinant FGF-5 purified from E. coli [PMID:8386828]; BaF3 cells with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF5 is flagged secreted; FGFR1 is flagged as a transmembrane receptor [flag].","caveats":"Main binding paper was read as abstract only; the KD range is shared with FGFR2. The BaF3 quote is browser-read and pending spot-check.","key_references":[{"PMID":"8386828","why":"KD and autophosphorylation for FGF-5 with FGFR1"},{"PMID":"8663044","why":"BaF3 receptor specificity survey"}],"covers":["LR000626","LR004110"]},"LR011220":{"pair":"GDF7 -> ACVR1B","headline":"GDF7 -> ACVR1B rests on a GtoPdb agonist record alone; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. One paper was judged abstract-insufficient, so it gave no confirmation.","key_references":[],"covers":["LR011220"]},"LR004200":{"pair":"GHRL -> GHSR","headline":"Ghrelin is the established agonist of GHSR, supported by binding, functional and database evidence in several papers.","interaction_type":"direct binding","direction_and_effect":"Ghrelin was purified from rat stomach as an endogenous ligand of GHS-R, and the acylated peptide releases GH [PMID:10604470]. It acts as an agonist and stimulates signalling beyond the receptor basal activity [PMID:12907757]. LEAP2 is an endogenous antagonist that inhibits GHSR activation by ghrelin [PMID:29233536]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Octanoylation at Ser3 is essential for activity [PMID:10604470]; desoctanoylated ghrelin did not compete for binding [PMID:11314756]. Glu3.33 is an obligatory anchor residue for ghrelin agonists [PMID:21402696]. A dimer model proposes ghrelin activates one protomer [PMID:15905359].","affinity_potency":[{"value":"4.6-5.4 x 10(-7) mol/l","assay":"competition for 125I-Tyr-Ala-hexarelin binding (ghrelin and cortistatin similar)","system":"human pituitary membranes","cite":"PMID:11227737"}],"species_and_systems":"Human tissue membranes and transfected COS-7/HEK293 cells [PMID:11314756][PMID:12907757]; rat stomach purification [PMID:10604470]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted, receptor transmembrane [flag]; ghrelin is a stomach-derived circulating hormone in the abstract [PMID:29233536].","caveats":"All papers abstract only. The receptor shows strong ligand-independent signalling, so ghrelin adds modestly to the baseline [PMID:12907757]. Co-applied synthetic agonists can modulate ghrelin signalling [PMID:15905359]. PMID 21402696 concerns a synthetic agonist, with ghrelin only as background.","key_references":[{"PMID":"10604470","why":"Purification of ghrelin as the GHS-R ligand"},{"PMID":"11314756","why":"125I-ghrelin binding to human membranes; octanoylation required"},{"PMID":"29233536","why":"LEAP2 antagonism of ghrelin at GHSR"}],"covers":["LR000717","LR004200"]},"LR009597":{"pair":"GNAS -> VIPR1","headline":"Database-asserted only: one BioGRID affinity-capture record; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists Affinity Capture-Western [PMID:11812005]; species and cell system not reported in our evidence.","localisation_and_range":"VIPR1 is annotated as a transmembrane receptor [flag]; GNAS is intracellular.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. One curated judgement: 'different_entity'.","key_references":[],"covers":["LR009597"]},"LR005979":{"pair":"HJV -> HFE","headline":"HJV and HFE bind each other in transfected cells and form a membrane complex with TfR2; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"HFE and TfR2 bind HJV in a non-competitive manner, and HFE, TfR2 and HJV form a multi-protein membrane complex [PMID:22728873]. HJV competes with TfR1 for HFE binding, implicating this in iron sensing [PMID:22728873]. Effect on signalling is not reported in our evidence.","molecular_requirements":"TfR2 is part of the complex; TfR2-ECD residues 120-139 are critical for both HFE and HJV binding [PMID:22728873].","affinity_potency":[],"species_and_systems":"Human proteins in transfected HuH7 cells, using glycerol-gradient sedimentation and co-immunoprecipitation [PMID:22728873]. Mouse pair is ortholog-inferred.","localisation_and_range":"HJV is annotated as secreted and HFE as a transmembrane receptor [flag].","caveats":"One paper, read as an abstract. Co-immunoprecipitation in a complex could reflect indirect contact. HJV and HFE are not a conventional ligand-receptor pair; the receptor role of HFE is annotation only.","key_references":[{"PMID":"22728873","why":"HFE and TfR2 bind HJV in a membrane complex"}],"covers":["LR002715","LR005979"]},"LR007995":{"pair":"HLA-E -> VSIR","headline":"HLA-E reported as a direct ligand of VISTA (VSIR) from a large recombinant interaction screen; single paper.","interaction_type":"direct binding","direction_and_effect":"A high-throughput recombinant screen identified HLA-E and HLA-F as endogenous non-tumour ligands for the checkpoint receptor VISTA [PMID:35922511]. Activating or inhibitory effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the two proteins.","affinity_potency":[],"species_and_systems":"Human recombinant proteins in a screen of the human immune-cell surface proteome [PMID:35922511].","localisation_and_range":"HLA-E flagged secreted and transmembrane, VSIR transmembrane [flag]; the screen used recombinant proteins, so range is not tested.","caveats":"Single study; the excerpts give no affinity for this pair, and the follow-up functional work is not described. Authors state that each interaction merits individual study [PMID:35922511].","key_references":[{"PMID":"35922511","why":"screen discovering HLA-E/HLA-F as VISTA ligands"}],"covers":["LR007995"]},"LR005988":{"pair":"HMGB1 -> TLR4","headline":"HMGB1 is reported to act through TLR4 (proconvulsant in mice); database records include direct-binding assays, but the paper evidence is functional.","interaction_type":"functional only","direction_and_effect":"HMGB1 released from neurons and glia interacts with TLR4 in a proconvulsant pathway; antagonists of HMGB1 and TLR4 reduce seizures, and TLR4-defective C3H/HeJ mice are resistant to kainate-induced seizures [PMID:20348922]. The annotated modulatory effect is stimulatory [flag].","molecular_requirements":"Reactome describes HMGB1 binding the TLR4:LY96 complex [DB:Reactome]; UniProt says signalling through TLR4 seems to implicate LY96/MD-2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"C57BL/6 mice and TLR4-defective C3H/HeJ mice; increased HMGB1 and TLR4 expression also seen in human epileptogenic tissue [PMID:20348922].","localisation_and_range":"HMGB1 is flagged as secreted [flag]; released from neurons and glia in tissue [PMID:20348922].","caveats":"The paper was read as an abstract only and does not report binding. Binding support comes from IntAct (co-immunoprecipitation, surface plasmon resonance) [DB:IntAct] and Reactome. One further judged row is still pending.","key_references":[{"PMID":"20348922","why":"Mouse seizure models: HMGB1-TLR4 pathway, antagonists and TLR4-mutant mice"}],"covers":["LR002740","LR005988"]},"LR006000":{"pair":"HSPA4 -> LRP1","headline":"Mouse-cell evidence only, from an abstract: released Hsp70 acts via TLR4 and CD91 (LRP1) to drive migration. Human pair is ortholog-projected.","interaction_type":"functional only","direction_and_effect":"Hsp70 released in membrane vesicles by mouse mesoangioblasts interacts in an autocrine manner with TLR4 and CD91 to stimulate migration [PMID:27925208]. Downstream involvement of PI3K/AKT and NF-kB is reported [PMID:27925208].","molecular_requirements":"TLR4 and CD91 are named together, and whether LRP1 acts alone or with TLR4 is not reported in our evidence [PMID:27925208].","affinity_potency":[],"species_and_systems":"Mouse mesoangioblasts in vitro; the human interaction is inferred from ortholog projection, and the mouse pair is a direct entry [PMID:27925208].","localisation_and_range":"HSPA4 is flagged secreted [flag]; the paper describes release on membrane vesicles with autocrine action [PMID:27925208].","caveats":"Read as abstract only. The paper's protein is called Hsp70, which the dossier assigns to HSPA4; no binding or affinity data.","key_references":[{"PMID":"27925208","why":"Autocrine vesicle-released Hsp70 acting via TLR4 and CD91 on mouse mesoangioblast migration"}],"covers":["LR002753","LR006000"]},"LR008967":{"pair":"IL16 -> KCNJ4","headline":"Database-asserted only: a single holdup-assay record links IL16 and KCNJ4; no papers support a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. IntAct EBI-67807634 reports a direct interaction by holdup assay [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Holdup assay (IntAct, PMID 36115835 per record) [DB:IntAct]; species of the assay is not reported in our evidence.","localisation_and_range":"IL16 is annotated as secreted [flag]; no localisation annotation for the partner in our evidence.","caveats":"No curated paper evidence; the partner was judged a different entity in our curation. A binding-assay hit between two proteins does not establish a ligand-receptor signalling relationship.","key_references":[],"covers":["LR008967"]},"LR008958":{"pair":"JAM3 -> ITGB1","headline":"No paper confirms JAM3 binding to ITGB1; support is Reactome records of an alpha4beta1:JAM2:JAM3 complex only.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records alpha4beta1 integrin binding JAM2:JAM3 and an integrin alpha4beta1:JAM2:JAM3 complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"The Reactome record involves the alpha4beta1 heterodimer together with a JAM2:JAM3 pair, so ITGB1 alone is not shown to bind JAM3 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the Reactome human records [DB:Reactome].","localisation_and_range":"Localisation is not reported in our evidence; the Reactome complex is placed at the plasma membrane [DB:Reactome].","caveats":"No confirmed papers; the judged papers were review-only or abstract-insufficient, so support is database-only. The Reactome record concerns a JAM2:JAM3 pair with alpha4beta1, not JAM3 alone with ITGB1 [DB:Reactome].","key_references":[],"covers":["LR008958"]},"LR011004":{"pair":"LAMA5 -> ITGA2:ITGB1","headline":"No paper evidence; only a PDB structure record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a PDB entry containing chains of LAMA5 (O15230) and ITGA2 (P05556) [DB:PDB 7CEC].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMA5 flagged secreted [flag].","caveats":"Rests on a database structure record alone; one abstract-insufficient paper was judged. The PDB detail lists no ITGB1 chain.","key_references":[],"covers":["LR011004"]},"LR001005":{"pair":"LAMB3 -> ITGA3","headline":"LAMB3 (in laminin-332) binds integrin alpha3 with Kd 14 nM, and keratinocyte adhesion to epiligrin depends on alpha3beta1.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Cell adhesion to immunopurified epiligrin was inhibited with an anti-alpha3beta1 antibody [PMID:2032285]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder is the alpha3beta1 heterodimer; the ligand is the assembled heterotrimer, not LAMB3 alone [PMID:16413178]. Epiligrin has three disulfide-bonded subunits [PMID:2032285].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human foreskin keratinocytes [PMID:2032285]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. PMID:2032285 was read as abstract only; it is a functional adhesion result, not direct binding.","key_references":[{"PMID":"16413178","why":"Kd for alpha3beta1 vs laminin-332, full text"},{"PMID":"2032285","why":"Keratinocyte adhesion to epiligrin blocked by anti-alpha3beta1, abstract only"}],"covers":["LR001005","LR004423"]},"LR001014":{"pair":"LAMC2 -> ITGA3","headline":"Recombinant integrin alpha3beta1 binds laminin-332 (contains LAMC2) with Kd 14 nM; LAMC2 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 showed clear specificity for laminin-332 in solid-phase binding [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The tested ligand is the assembled laminin-332 heterotrimer and the receptor the alpha3beta1 heterodimer; the paper never tests individual chains [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha3beta1 ectodomain","cite":"PMID:16413178"}],"species_and_systems":"Human ligand and receptor, recombinant soluble proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Evidence is for laminin-332 and the integrin heterodimer, not LAMC2 and ITGA3 chains in isolation.","key_references":[{"PMID":"16413178","why":"Kd of recombinant laminin-binding integrins for laminin isoforms"}],"covers":["LR001014","LR004432"]},"LR001023":{"pair":"LGALS3BP -> ITGB1","headline":"Cell adhesion to recombinant LGALS3BP is blocked by anti-integrin beta1 antibodies, and a BioGRID record exists; indirect evidence for the pair.","interaction_type":"functional only","direction_and_effect":"Adhesion of cell lines to M2BP was inhibited by antibodies to integrin beta1 subunits but not alpha2 or alpha6 antibodies, RGD peptide or lactose; this excludes galectin-3 involvement [PMID:9501082].","molecular_requirements":"Beta1 subunit implicated by antibody blockade; the alpha partner is not identified in our evidence [PMID:9501082].","affinity_potency":[],"species_and_systems":"Recombinant human M2BP from 293 cells with cell lines; mouse pair is ortholog-inferred [PMID:9501082].","localisation_and_range":"M2BP is described as a protein of the extracellular matrix, forming oligomers of 1000-1500 kDa [PMID:9501082]; ligand has a secreted flag [flag].","caveats":"Abstract only. Antibody inhibition of adhesion is not direct binding; the paper's title mentions binding beta1 integrins but the abstract shows only the blockade. BioGRID lists a Reconstituted Complex record [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"9501082","why":"M2BP-mediated cell adhesion is inhibited by anti-integrin beta1 antibodies"}],"covers":["LR001023","LR004441"]},"LR007977":{"pair":"LIF -> IL6ST:LIFR","headline":"LIF activates the gp130/LIFR heterodimer; supported by mutagenesis binding studies, a Xenopus functional study and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"LIF acts through a heterodimeric receptor of gp130 (IL6ST) and LIFR [PMID:12707269]; signalling was studied in Xenopus embryos, agonist [PMID:30578761]. GtoPdb records agonist [DB:GtoPdb].","molecular_requirements":"Both chains are required in the complex: LIF binding to LIFR maps to the Ig-like domain, mainly Phe-328 [PMID:12601009]; gp130 is named as the high-affinity converter (curator note) [PMID:12601009]. Site III binding to LIFR maps to an FXXK motif shared with CT-1 and OSM [PMID:12707269]. PDB 1PVH and 8D6A contain both chains [DB:PDB 1PVH][DB:PDB 8D6A].","affinity_potency":[],"species_and_systems":"Human LIFR mutagenesis and binding assays [PMID:12601009][PMID:12707269]; Xenopus embryos with human proteins listed [PMID:30578761].","localisation_and_range":"LIF is flagged secreted; IL6ST is flagged transmembrane [flag]; a soluble ligand acting on a membrane complex.","caveats":"All three papers read as abstracts only. No numeric affinity is given in our evidence. Humanising mutations Q251E and N321D increased affinity for human LIF, but values are not reported [PMID:12601009].","key_references":[{"PMID":"12601009","why":"Alanine scan maps LIF binding site on LIFR Ig-like domain, Phe-328"},{"PMID":"12707269","why":"Shared binding motif for LIF, CT-1, OSM on LIFR"},{"PMID":"30578761","why":"LIF signalling via LIFR/IL6ST in Xenopus"}],"covers":["LR007977"]},"LR001032":{"pair":"LPL -> LRP1","headline":"LPL binds LRP1 with nanomolar affinity in three abstract-only papers; LRP1 acts as a clearance receptor.","interaction_type":"direct binding","direction_and_effect":"LPL competed with activated alpha2-macroglobulin and RAP for LRP binding, and an anti-LRP antibody blocked cellular degradation of 125I-LPL, so LRP mediates LPL uptake [PMID:1281473]. A carboxyl-terminal LPL fragment (residues 378-448) bound LRP and inhibited lipase-mediated lipoprotein uptake, acting as an antagonist of that uptake [PMID:7989348].","molecular_requirements":"The LRP-binding region lies in the C-terminal domain of LPL, residues 313-448, which lacks the catalytic site [PMID:7510694]. Mutating Lys407 to Ala reduced affinity about 10-fold; Trp393/Trp394 mutations abolished lipoprotein binding but had little effect on LRP interaction [PMID:7510694]. Binding of the fragment was blocked by heparin [PMID:7989348].","affinity_potency":[{"value":"KD 18 nM","assay":"125I-LPL binding to purified LRP, solid-phase","system":"bovine milk LPL, human LRP","cite":"PMID:1281473"},{"value":"Ki 6.8 nM","assay":"competition with alpha2M* on LDL-receptor-deficient fibroblasts","system":"bovine milk LPL","cite":"PMID:1281473"},{"value":"KD 2.8 nM","assay":"purified LRP binding to LPL-coated wells","system":"human LPL, human LRP","cite":"PMID:7510694"},{"value":"KD 5 nM","assay":"purified LRP binding to LPLC-coated wells","system":"human LPL C-terminal fragment","cite":"PMID:7510694"}],"species_and_systems":"Purified protein and cultured fibroblast systems; ligand was bovine milk LPL in one paper and human LPL fragments in the others [PMID:1281473][PMID:7510694].","localisation_and_range":"LPL is annotated secreted [flag]. The binding promotes cellular uptake and degradation [PMID:1281473].","caveats":"All three papers read as abstracts only. LRP1 is a catabolic receptor here, not a signalling receptor [PMID:1281473]. Much evidence uses fragments rather than full-length LPL [PMID:7510694][PMID:7989348].","key_references":[{"PMID":"7510694","why":"Maps LRP binding to LPL C-terminal domain; KD 2.8 nM"},{"PMID":"1281473","why":"LPL binds LRP with KD 18 nM and is internalised"},{"PMID":"7989348","why":"C-terminal fragment binds LRP and inhibits lipase-mediated uptake"}],"covers":["LR001032","LR004446"]},"LR001041":{"pair":"LTA -> TNFRSF1B","headline":"LT alpha binds the 75-kDa TNF receptor, but with lower affinity than TNF and without clear signalling in the one cell system examined.","interaction_type":"direct binding","direction_and_effect":"LT still had approximately half of the affinity to p75R of TNF by Scatchard analysis, yet LT was unable to signal through p75R on U-937 cells in cytotoxicity [PMID:8123048]. The database annotation reads Stimulatory; the paper does not support signalling here.","molecular_requirements":"UniProt says the LTA homotrimer binds TNFR2/TNFBR [DB:UniProt]. Reactome lists LTA trimer binding TNFRSF1A,1B,14 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human U-937 monocytic cells [PMID:8123048]. The expression-cloning paper used a human lung fibroblast library [PMID:2160731].","localisation_and_range":"LTA flagged secreted; the receptor flagged both secreted and transmembrane [flag].","caveats":"Both papers read as abstracts only. No numeric Kd is given in our evidence. The expression-cloning abstract does not name which TNF receptor was cloned [PMID:2160731]. BioGRID lists reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8123048","why":"Scatchard binding of LT to p75R vs TNF"},{"PMID":"2160731","why":"Cloned TNF receptor family member binds TNF-beta"}],"covers":["LR001041","LR004454"]},"LR001050":{"pair":"MADCAM1 -> ITGB7","headline":"MADCAM1 binds integrin alpha4beta7; ITGB7 is the specificity-determining chain, but the pair rests on heterodimer data.","interaction_type":"direct binding","direction_and_effect":"MADCAM1 acts as a stimulatory adhesion ligand; alpha4beta7 is a receptor for MAdCAM-1 [PMID:7687523]. A beta7 region (residues 46-386) accounts for specificity of alpha4beta7 binding to MAdCAM-1, with a MIDAS-like domain at residues 176-250 [PMID:9233649].","molecular_requirements":"ITGB7 needs alpha4 to bind; alpha4beta1 does not bind MAdCAM-1 despite sharing alpha4 [PMID:7687523][PMID:9233649]. Mn2+ activation enhances binding [PMID:7687523].","affinity_potency":[],"species_and_systems":"Human beta7/beta1 chimeric constructs [PMID:9233649]; human lymphocyte lines in the force-spectroscopy study [PMID:29789438]; species unspecified in PMID:7687523. Mouse pair is ortholog-inferred.","localisation_and_range":"MADCAM1 is flagged transmembrane, not secreted [flag]; contact-dependent.","caveats":"Papers other than PMID:29789438 were read as abstracts only. Chain-only entry: the binding entity is the alpha/beta pair (curator note). CCL25 and CXCL10 switch alpha4beta7 between MAdCAM-1 and VCAM-1 preference [PMID:29789438]. A PDB entry has chains of both MADCAM1 and ITGB7 partners [DB:PDB 9P95].","key_references":[{"PMID":"9233649","why":"beta7 domain mapping for MAdCAM-1 binding"},{"PMID":"7687523","why":"alpha4beta7 identified as MAdCAM-1 receptor"},{"PMID":"29789438","why":"chemokine-dependent conformers and single-bond force data"}],"covers":["LR001050","LR004463"]},"LR001104":{"pair":"NLGN1 -> NRXN3","headline":"Rests on a general neuroligin-neurexin binding paper and a BioGRID record; NRXN3 specifically is not pinned down.","interaction_type":"direct binding","direction_and_effect":"Neuroligin 1 binds a subset of neurexins and binds beta-neurexins as native brain and recombinant proteins [PMID:8576240]. Effect on NRXN3 specifically is not reported in our evidence.","molecular_requirements":"Tight binding only to beta-neurexins lacking an insert at splice site 4 [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat (curator-listed) binding assays [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Abstract says neuroligin binds 'a subset of neurexins', so NRXN3 is not shown individually; the curator notes a paralogue caveat. Abstract only. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin-neurexin binding, splice-dependent"}],"covers":["LR001104","LR004515"]},"LR001113":{"pair":"NMS -> NMUR1","headline":"Functionally supported agonist pair from one abstract-level deorphanisation paper in rat, plus GtoPdb and UniProt records.","interaction_type":"functional only","direction_and_effect":"NMS is an agonist of the neuromedin U receptor; it was purified from rat brain as an endogenous ligand of FM-4/TGR-1 (NMU receptors) and ICV administration activates SCN neurons and phase-shifts circadian activity in rats [PMID:15635449]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond a receptor chain; a PDB structure with these two chains exists [DB:PDB 7W56].","affinity_potency":[{"value":"pIC50 10.0","assay":"as recorded for the paper's curated affinity field","system":"rat","cite":"PMID:15635449"}],"species_and_systems":"Rat peptide and rat receptor [PMID:15635449]; human and mouse entries are not directly tested in our evidence. UniProt describes NMUR1 as a receptor for NMU and NMS [DB:UniProt].","localisation_and_range":"NMS is flagged secreted and the paper proposes autocrine and/or paracrine action in the SCN [PMID:15635449][flag].","caveats":"Single paper, read as abstract only. The abstract identifies the receptor as FM-4/TGR-1 and does not distinguish NMUR1 from NMUR2, so receptor-subtype specificity is not established by it. The affinity assay is not described in our evidence.","key_references":[{"PMID":"15635449","why":"Identification of NMS as endogenous NMU-receptor ligand with in vivo circadian effect"}],"covers":["LR001113","LR004524"]},"LR001122":{"pair":"NPB -> NPBWR1","headline":"Neuropeptide B is an agonist of NPBWR1 (GPR7), shown by purification and binding in cells.","interaction_type":"direct binding","direction_and_effect":"Neuropeptide B was purified from bovine hypothalamus using cAMP-inhibitory activity on GPR7 cells [PMID:12118011], and four peptides inhibited forskolin-stimulated cAMP accumulation through a pertussis toxin-sensitive mechanism [PMID:12401809]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone is enough; bromination of the N-terminal Trp did not influence binding [PMID:12118011].","affinity_potency":[{"value":"low nanomolar","assay":"binding assay","system":"CHO-K1 cells expressing GPR7","cite":"PMID:12401809"}],"species_and_systems":"Bovine ligand with receptor cells for purification [PMID:12118011]; human receptors in CHO-K1 cells [PMID:12401809]. Both abstract only. Mouse pair ortholog-inferred.","localisation_and_range":"NPB is flagged secreted [flag]; peptide, endocrine or paracrine.","caveats":"Not selective: the peptides also bound GPR8 with similar affinity [PMID:12401809]. One further abstract was insufficient. GtoPdb gives pIC50 without values in our dossier [DB:GtoPdb].","key_references":[{"PMID":"12118011","why":"Purification of the endogenous GPR7 ligand, brominated neuropeptide B"},{"PMID":"12401809","why":"L7 peptides (NPB) bind GPR7 and GPR8 with low nanomolar affinity"}],"covers":["LR001122","LR004533"]},"LR001131":{"pair":"NPPB -> NPR2","headline":"BNP activates NPR2 (ANP-B receptor) preferentially over ANP in one 1989 study using porcine BNP.","interaction_type":"functional only","direction_and_effect":"The cloned human ANP-B receptor is preferentially activated by porcine BNP rather than human alpha-ANP [PMID:2570358].","molecular_requirements":"Receptor-only guanylate cyclase; no further requirements reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor, porcine BNP, abstract-only [PMID:2570358]. Human BNP not tested in the evidence shown. BioGRID reconstituted complex records [DB:BioGRID].","localisation_and_range":"Not reported beyond annotation; BNP is flagged secreted [flag].","caveats":"Single abstract-only paper with porcine ligand; no affinity given. Other evidence is BioGRID only.","key_references":[{"PMID":"2570358","why":"Cloning of ANP-B receptor with BNP preference"}],"covers":["LR001131","LR004541"]},"LR003003":{"pair":"NRCAM -> NFASC","headline":"NRCAM binds neurofascin on axons in one abstract-level coculture paper, plus a Reactome heterodimer record.","interaction_type":"direct binding","direction_and_effect":"An Nr-CAM-Fc fusion bound directly to neurons and clustered and coprecipitated neurofascin on axons; it inhibited Na+ channel and ankyrin G accumulation at the node [PMID:11728309]. Reactome lists an NFASC:NRCAM complex [DB:Reactome R-HSA-373686].","molecular_requirements":"Not reported in our evidence beyond the two partners; which neurofascin isoform is needed is not stated.","affinity_potency":[],"species_and_systems":"DRG neuron-Schwann cell cocultures with an Nr-CAM-Fc fusion; species not stated in the dossier [PMID:11728309]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Membrane-bound cell adhesion molecules on the axon surface (abstract) [PMID:11728309]; NFASC is flagged not secreted [flag]. Juxtacrine/contact signalling.","caveats":"One paper, abstract only; the Fc fusion is a recombinant reagent and the paper frames the interaction as 'possibly' relevant. The Reactome record cites an older paper [DB:Reactome R-HSA-373730]. Ligand-receptor direction is arbitrary for a homophilic-type adhesion pair.","key_references":[{"PMID":"11728309","why":"Nr-CAM-Fc binds and coprecipitates neurofascin on axons"}],"covers":["LR003003","LR006227"]},"LR008598":{"pair":"NRG3 -> ERBB2:ERBB4","headline":"NRG3 binds and activates ERBB4; the ERBB2:ERBB4 complex row rests on an abstract that shows ERBB4 only.","interaction_type":"direct binding","direction_and_effect":"The EGF-like domain of NRG3 binds the ErbB4 extracellular domain in vitro, binds ErbB4 on cells and stimulates its tyrosine phosphorylation [PMID:9275162].","molecular_requirements":"The paper shows ErbB4 only; ErbB2 is mentioned only as an NRG1 receptor in background, so the ERBB2 member is not supported by this paper [PMID:9275162]. GtoPdb lists NRG3-ERBB4 only [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, in vitro binding and cells [PMID:9275162].","localisation_and_range":"Annotated secreted and transmembrane [flag]. Expression restricted to nervous system [PMID:9275162].","caveats":"Abstract only. The evidence sentence quoted by curators is NRG1 background. No affinity reported. A second paper was judged abstract_insufficient.","key_references":[{"PMID":"9275162","why":"NRG3 binds and activates ErbB4"}],"covers":["LR008598"]},"LR003012":{"pair":"NRP1 -> NRP1","headline":"NRP1 interacting with NRP1 rests on one abstract-level biosensor paper; homotypic binding is lightly evidenced.","interaction_type":"direct binding","direction_and_effect":"Npn-1 interacts with Npn-1 immobilized on an optical biosensor surface, alongside FGFs and HGF/SF [PMID:15695515]. Effect for this pair is not reported.","molecular_requirements":"Interactions were ionic-strength dependent and heparin-inhibited, suggesting a heparin-mimetic site [PMID:15695515]. BioGRID has a two-hybrid record and IntAct a coimmunoprecipitation record [DB:BioGRID][DB:IntAct].","affinity_potency":[],"species_and_systems":"Optical biosensor, recombinant proteins; species not stated beyond human; human cells used for the FGF-2 potentiation assay [PMID:15695515]. Mouse pair is projected from human.","localisation_and_range":"NRP1 is flagged secreted, receptor and transmembrane [flag].","caveats":"Single paper, abstract only; the NRP1 self-interaction is one item in a list, with no kinetics given for it. Biological relevance and direction not shown; this is homo-oligomerization rather than ligand-receptor signalling.","key_references":[{"PMID":"15695515","why":"Biosensor shows Npn-1 binding to immobilized Npn-1"}],"covers":["LR003012","LR006236"]},"LR003021":{"pair":"NRXN1 -> LRRTM4","headline":"Well supported: three papers show direct binding of neurexin-1 forms to LRRTM4, including SS4-independent and heparan sulfate-dependent aspects.","interaction_type":"direct binding","direction_and_effect":"Immobilised Ig-neurexin-1beta captured all LRRTM isoforms (LRRTM1-4) from HEK293 cells [PMID:20064387]. LRRTM4-Fc bound Nrx1beta with or without S4 in a cell-free co-precipitation [PMID:23911103]. Nrx1gamma was identified as a synapse organizer with LRRTM4 as its postsynaptic ligand [PMID:31995730].","molecular_requirements":"Unlike LRRTM2, LRRTM4 binds neurexin-1beta independent of SS4 [PMID:23911103]. LRRTMs require the heparan sulfate modification of neurexin to induce presynaptic differentiation, and binding to the HS is sufficient for LRRTM3 and LRRTM4 [PMID:31995730].","affinity_potency":[],"species_and_systems":"Recombinant proteins in HEK293 and cell-free assays; species unspecified in curation. Human pair is ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Glypican is a major LRRTM4 partner and few neurexin spectra were seen in LRRTM4 affinity chromatography [PMID:23911103]. 31995730 read as abstract only.","key_references":[{"PMID":"23911103","why":"LRRTM4-Fc binds Nrx1beta with or without S4"},{"PMID":"20064387","why":"Ig-neurexin-1beta pull-down of LRRTM1-4"},{"PMID":"31995730","why":"Nrx1gamma/LRRTM4 and HS-dependent organizer function"}],"covers":["LR003021","LR006245"]},"LR003030":{"pair":"NRXN3 -> DAG1","headline":"Alpha-neurexins including neurexin 3alpha bind dystroglycan directly via the second LNS domain, in rat brain extract.","interaction_type":"direct binding","direction_and_effect":"The second LNS domain of neurexin 1alpha, 2alpha and 3alpha forms tight Ca2+-dependent complexes with dystroglycan [PMID:11470830].","molecular_requirements":"A single isolated LNS domain without flanking sequences fully binds; only alpha-neurexins with the second or sixth LNS domain captured dystroglycan [PMID:11470830]. The abstract adds that binding requires dystroglycan glycosylation and is regulated by neurexin alternative splicing [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig-fusion protein affinity chromatography with rat brain extract and domain deletions [PMID:11470830]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane, NRXN3 transmembrane [flag]; the abstract describes neuronal cell-surface dystroglycan [PMID:11470830].","caveats":"Evidence concerns alpha-neurexin LNS domains; beta-neurexin binding is not reported in the excerpts. Both species rows are projected from rat data.","key_references":[{"PMID":"11470830","why":"Neurexin 3alpha LNS2 binds dystroglycan, Ca2+ dependent"}],"covers":["LR003030","LR006254"]},"LR007986":{"pair":"NXNL1 -> BSG:SLC16A1","headline":"Complex entry for RdCVF acting through BSG1 coupled to a glucose transporter; supported by the same single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"RdCVF binds BSG1, and BSG1 binds the glucose transporter GLUT1, increasing glucose entry into cones and survival through aerobic glycolysis [PMID:25957687]. UniProt says SLC16A1 with BSG promotes cone survival by enhancing glycolysis [DB:UniProt].","molecular_requirements":"The receptor is a BSG:SLC16A1 complex; the abstract names the partner as GLUT1, so the SLC16A1 assignment comes from the curation row and UniProt [DB:UniProt]. Direct RdCVF binding is shown for BSG1 alone [PMID:25957687].","affinity_potency":[],"species_and_systems":"Human entry, not ortholog-inferred, but experimental species is not stated in the abstract; retinitis pigmentosa model [PMID:25957687].","localisation_and_range":"Secreted ligand [flag]; transmembrane complex [flag].","caveats":"Single abstract-only paper. Whether RdCVF contacts SLC16A1 itself is not reported; evidence is for BSG1 binding plus a downstream transporter effect. GLUT1 and SLC16A1 are different names in the dossier, so this complex assignment should be treated cautiously.","key_references":[{"PMID":"25957687","why":"RdCVF-BSG1 binding and BSG1-GLUT1 glucose uptake mechanism"}],"covers":["LR007986"]},"LR006798":{"pair":"PDGFC -> FLT4","headline":"PDGFC -> FLT4 rests on a single GtoPdb record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; GtoPdb lists Type=None; Action=None [DB:GtoPdb]. The pair is annotated Stimulatory in the project record.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PDGFC is flagged both secreted and transmembrane in the entity annotation [flag]; FLT4 is flagged a transmembrane receptor [flag].","caveats":"No verified papers; three papers were judged abstract-insufficient. The only support is a database assertion with no stated type or affinity.","key_references":[],"covers":["LR006798"]},"LR001203":{"pair":"PDYN -> OPRM1","headline":"PDYN -> OPRM1 is asserted by GtoPdb and Reactome only; no curated paper was verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records Agonist, Full agonist [DB:GtoPdb]. Reactome has an Opioid:MOR complex and an opioid-binds-MOR reaction [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PDYN flagged secreted; OPRM1 transmembrane [flag].","caveats":"Ten papers were abstract-insufficient and two were a different entity; none verified. The Reactome records concern generic opioid, not specifically PDYN.","key_references":[],"covers":["LR001203","LR004612"]},"LR003102":{"pair":"PIP -> AQP5","headline":"PIP is the AQP5 C-terminus-binding protein in mouse lacrimal gland, an intracellular trafficking relationship rather than a classical extracellular ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"A 17-kDa AQP5 C-terminal-peptide-binding protein from ICR mouse lacrimal glands was identified by LC-MS/MS as PIP; antisense PIP oligonucleotides decreased apical AQP5 immunostaining, suggesting PIP binding drives AQP5 apical transport [PMID:18696337]. Curated effect direction: agonist [PMID:18696337].","molecular_requirements":"The binding site is the AQP5 C-terminal portion [PMID:18696337]. Other requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; lacrimal gland homogenates, ICR versus NOD (Sjogren's model) mice [PMID:18696337]. The human pair is projected from mouse (ortholog_inferred).","localisation_and_range":"PIP carries a secreted flag [flag]; the paper's binding is to the AQP5 C-terminus in gland homogenate [PMID:18696337].","caveats":"Abstract only. Binding was to a synthetic C-terminal peptide on an affinity column, not to intact receptor on a cell surface. In NOD mice a 21-kDa protein (MUP4) bound instead [PMID:18696337]. Human evidence: none in our evidence.","key_references":[{"PMID":"18696337","why":"PIP identified as AQP5 C-terminus binder in mouse lacrimal gland"}],"covers":["LR003102","LR006323"]},"LR001221":{"pair":"PLAT -> LRP1","headline":"tPA bound to PAI-1 binds LRP1 for clearance, and LRP1 binds tPA on neurons; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"tPA-inhibitor complexes bound LRP in solution, and their endocytosis and degradation in cells was reduced by anti-LRP antibodies and RAP [PMID:1502153]. In hippocampal neurons LRP was the major cell-surface receptor that bound tPA, and tPA binding enhanced cyclic AMP-dependent protein kinase activity [PMID:10632583]. UniProt says LRP1 interacts with tPA alone or in complex with SERPINE1 [DB:UniProt Q07954].","molecular_requirements":"The species bound in [PMID:1502153] is the tPA-PAI-1 complex, not free tPA. LRP is a heterodimeric receptor [PMID:1502153].","affinity_potency":[],"species_and_systems":"Human ligand and receptor labels for the 1992 paper; [PMID:10632583] used mouse hippocampal slices with tPA knockout mice (ligand species unspecified). Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted tPA per flag [flag]; LRP1 is described as a ubiquitous membrane receptor [PMID:1502153].","caveats":"Abstract only. Free tPA binding is shown only in neurons [PMID:10632583]; clearance function is for the complex [PMID:1502153]. Numeric affinity not reported in our evidence.","key_references":[{"PMID":"1502153","why":"tPA-PAI-1 complexes bind LRP and are cleared"},{"PMID":"10632583","why":"LRP is the major tPA-binding receptor on hippocampal neurons"}],"covers":["LR001221","LR004624"]},"LR003111":{"pair":"PLAUR -> ITGA6","headline":"Direct cell-based binding of soluble uPAR to alpha6 (ITGA6) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta1 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003111","LR006332"]},"LR001230":{"pair":"PLG -> ITGA9","headline":"Plasmin(ogen) kringles bind integrin alpha9beta1 in CHO cells; chain-level row for ITGA9.","interaction_type":"direct binding","direction_and_effect":"Plasmin specifically interacts with alpha9beta1 and induced migration of alpha9-CHO cells; migration needed kringle binding, plasmin catalytic activity and simultaneous PAR-1 activation [PMID:15247268]. Angiostatin alone did not induce migration [PMID:15247268].","molecular_requirements":"Needs kringle binding plus catalytic activity and PAR-1; alpha9 is tested as the alpha9beta1 heterodimer [PMID:15247268].","affinity_potency":[],"species_and_systems":"Human proteins on recombinant CHO cells; abstract only [PMID:15247268].","localisation_and_range":"Ligand flagged secreted.","caveats":"The active species is plasmin, the cleaved form, not intact plasminogen; angiostatin is described as a ligand and antagonist of alpha9beta1 [PMID:15247268]. One further row abstract-insufficient.","key_references":[{"PMID":"15247268","why":"plasmin binds alpha9beta1 and needs PAR-1 for migration"}],"covers":["LR001230","LR004633"]},"LR003120":{"pair":"PLG -> MELTF","headline":"Membrane-bound melanotransferrin acts as a plasminogen binding site in cells; antibody and soluble-MTf blockade, abstract level.","interaction_type":"direct binding","direction_and_effect":"mMTf expression in CHO cells raised plasminogen binding about 2-fold and plasminogen activation about 2.5-fold; anti-MTf antibody L235 and soluble MTf abolished binding [PMID:15936756]. It promoted motility, migration and invasion about 3-fold [PMID:15936756].","molecular_requirements":"Membrane-bound MTf is the form studied; soluble truncated MTf blocks [PMID:15936756].","affinity_potency":[],"species_and_systems":"Human MTf in CHO cells and SK-MeL-28 melanoma cells; abstract only [PMID:15936756].","localisation_and_range":"Ligand flagged secreted; receptor membrane-bound (scaffold at cell surface).","caveats":"Described as a 'potential' plasminogen receptor; no affinity or purified-protein binding.","key_references":[{"PMID":"15936756","why":"melanotransferrin as cell-surface plasminogen receptor"}],"covers":["LR003120","LR006341"]},"LR001302":{"pair":"RLN3 -> RXFP3","headline":"Relaxin-3 is the well-supported high-affinity agonist of RXFP3, with binding and functional data across human, mouse and rat receptors.","interaction_type":"direct binding","direction_and_effect":"Relaxin-3 binds GPCR135 (RXFP3) and activates it: GTPgammaS binding is stimulated and cAMP accumulation inhibited [PMID:14522968]; H3 relaxin also activates ERK1/2 via G(i/o) proteins [PMID:17351017]. It is the only insulin/relaxin member reported to activate it [PMID:14522968].","molecular_requirements":"Not reported in our evidence beyond the single receptor chain. BioGRID lists a reconstituted complex and a protein-peptide record [DB:BioGRID]; a PDB entry 9KFI is listed [DB:PDB 9KFI].","affinity_potency":[{"value":"Kd 0.31 nM","assay":"125I-relaxin-3 binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.25 nM","assay":"GTPgammaS binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.35 nM","assay":"cAMP accumulation inhibition","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"IC50 or EC50 values close to 0.5 nM","assay":"binding and activation","system":"mouse, rat and human GPCR135","cite":"PMID:15367576"}],"species_and_systems":"Human recombinant receptor in CHO-K1 and HEK-293 cells [PMID:17351017]; mouse and rat GPCR135 showed very similar pharmacology to human [PMID:15367576]. The mouse pair is also listed as ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag]; brain co-expression is described [PMID:14522968].","caveats":"Papers were read as abstracts only. Relaxin-3 also acts on other relaxin-family receptors in our evidence (see RXFP1, RXFP4 pairs) [PMID:16411781]. Bradykinin did not activate GPCR135 [PMID:15367576].","key_references":[{"PMID":"14522968","why":"Deorphanisation with Kd and EC50 values"},{"PMID":"15367576","why":"Cross-species conservation of relaxin-3/GPCR135 pharmacology"},{"PMID":"17351017","why":"ERK1/2 signalling downstream of RXFP3"}],"covers":["LR001302","LR004700"]},"LR006789":{"pair":"RPS19 -> C5AR2","headline":"RPS19 -> C5AR2 is supported only by a GtoPdb agonist record; no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists RPS19 as agonist of C5AR2 [DB:GtoPdb]. Direct evidence is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"System not stated; the GtoPdb record cites PMID 11107061 [DB:GtoPdb].","localisation_and_range":"RPS19 carries a secreted flag [flag].","caveats":"Only database assertion; the cited paper was not among the judged papers (one review-only and one abstract-insufficient row exist). Affinity not given.","key_references":[],"covers":["LR006789"]},"LR001311":{"pair":"RSPO1 -> ZNRF3","headline":"RSPO1 binds ZNRF3 with micromolar affinity by crystal structure; it inhibits ZNRF3 function.","interaction_type":"direct binding","direction_and_effect":"ZNRF3 binds RSPO1 and LGR5-RSPO1 with micromolar affinity via the RSPO1 Fu1 domain [PMID:24349440]. Annotated antagonist: RSPO1 blocks ZNRF3 and thereby enhances Wnt signalling [PMID:24349440].","molecular_requirements":"RSPO1 Fu1 domain mediates binding; the interface buries ~1,200 \u00c52 [PMID:24349440]. The ZNRF3 site overlaps trans-interactions of 2:2 LGR5-RSPO1 complexes.","affinity_potency":[],"species_and_systems":"Human proteins, crystal structures; mouse pair listed as not inferred [PMID:24349440].","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract and excerpts are from a structural study; the affinity is stated only as micromolar, without a number. BioGRID and IntAct list FRET, SPR and reconstitution records [DB:BioGRID][DB:IntAct]. Receptor flag is generic.","key_references":[{"PMID":"24349440","why":"Crystal structure of ZNRF3-RSPO1 complex"}],"covers":["LR001311","LR004708"]},"LR001320":{"pair":"RSPO3 -> SDC4","headline":"Rspo3 binds syndecan 4 and drives Wnt/PCP signalling in Xenopus; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Rspo3 binds Sdc4 and together they activate Wnt/PCP signalling; this works by inducing Sdc4-dependent clathrin-mediated endocytosis, which the authors say is essential for PCP signal transduction [PMID:21397842].","molecular_requirements":"In gastrulation, Rspo3/PCP signalling requires Wnt5a and is transduced via Fz7, Dvl and JNK [PMID:21397842].","affinity_potency":[],"species_and_systems":"Xenopus embryos for the functional work [PMID:21397842]; curators record human ligand and receptor. The mouse pair is ortholog-inferred.","localisation_and_range":"RSPO3 is flagged secreted [flag]; syndecan 4 is a membrane proteoglycan, though its localisation is not stated in our flags.","caveats":"Abstract only; binding assay and affinity are not reported in our evidence. No database records support this pair. The signal is Wnt/PCP, distinct from canonical beta-catenin signalling.","key_references":[{"PMID":"21397842","why":"Rspo3 binds Sdc4 and induces Wnt/PCP signalling via endocytosis"}],"covers":["LR001320","LR004717"]},"LR003201":{"pair":"RTN4RL1 -> ADGRB1","headline":"Direct binding of RTN4RL1 to BAI1 shown by cell-surface binding, AVEXIS, aggregation and SPR across two full-text papers.","interaction_type":"direct binding","direction_and_effect":"RTN4RL1 binds the ADGRB1 ectodomain: ADGRB1 probes stained RTN4RL1-transfected cells and the ectodomains interacted directly in both bait-prey orientations [PMID:30477585]. RTN4RL1 was a top pulldown interactor of BAI1 and BAI3 ECDs [PMID:34758294]. RTN4RL1 loss in human neurons altered synapse density and size and increased axon length and branching [PMID:34758294]; direction of signalling is not reported.","molecular_requirements":"ADGRB1 TSR1-3 were sufficient for binding [PMID:30477585]. The BAI1 N-terminal domains including the TSRs formed a stable complex with RTN4RL1 ECD by SEC [PMID:34758294]. ADGRB2 did not bind the family [PMID:30477585].","affinity_potency":[],"species_and_systems":"HEK293 cells, recombinant ectodomains and human neurons [PMID:30477585][PMID:34758294]. Affinity by SPR is reported only as the range for the BAI/RTN4R family (1.9 nM to 30.0 nM); a value specific to RTN4RL1-BAI1 is not reported in our excerpts.","localisation_and_range":"Trans-cellular adhesion shown, so juxtacrine; RTN4RL1 is described as GPI-linked membrane protein [PMID:30477585][PMID:34758294]. RTN4RL1 has no secreted flag; ADGRB1 carries a secreted flag [flag].","caveats":"Single CRISPRa screen per bait [PMID:30477585]. ADGRB1 secreted flag looks odd for a membrane receptor [flag].","key_references":[{"PMID":"34758294","why":"binding, SPR family range and neuronal function"},{"PMID":"30477585","why":"CRISPRa screen with AVEXIS validation"}],"covers":["LR003201","LR006421"]},"LR003210":{"pair":"S100A10 -> HTR4","headline":"p11/S100A10 is a newly identified 5-HT4 interactor that raises surface expression and signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"p11 increases 5-HTR4 surface expression and facilitates 5-HTR4 signalling; p11 is required for behavioural antidepressant responses to 5-HTR4 stimulation in vivo [PMID:19211900].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"p11 and 5-HTR4 mRNA and protein are coexpressed in brain regions relevant to depression; in vivo behavioural work, species not stated in the abstract [PMID:19211900].","localisation_and_range":"S100A10 is not flagged secreted [flag]; the paper describes an accessory-protein role in receptor trafficking and signalling [PMID:19211900].","caveats":"Abstract only; binding method not reported in our evidence. The curator noted a corrupted receptor-symbol field in the source record.","key_references":[{"PMID":"19211900","why":"Identifies p11-5-HTR4 interaction and function"}],"covers":["LR003210","LR006430"]},"LR005010":{"pair":"Sbpl -> Cxcr4","headline":"Evidence is for PAUF associating with a CXCR4-TLR2 complex, not clear direct binding to CXCR4; weak for a ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"PAUF associated with the CXCR4-TLR2 complex in co-immunoprecipitation in HEK293T cells, and PAUF increased cAMP-mediated luciferase activity, abolished by the CXCR4 antagonist AMD3100 [PMID:20802527]. PAUF inhibited TLR2-mediated NF-kappaB activation, a CXCR4-dependent effect [PMID:20802527].","molecular_requirements":"CXCR4 appears to act with TLR2 as a possible co-receptor; the excerpts say CXCR4 might be a TLR2 co-receptor [PMID:20802527].","affinity_potency":[],"species_and_systems":"HEK293T and THP-1 (human) cells; The paper calls the protein PAUF; curators mapped it to Sbpl, and the mouse pair is ortholog-inferred. [PMID:20802527]","localisation_and_range":"PAUF is secreted [flag].","caveats":"Read as abstract plus excerpts. Direct PAUF-CXCR4 binding is not shown in our evidence, and the paper describes PAUF as a potential CXCR4 activator.","key_references":[{"PMID":"20802527","why":"PAUF, TLR2 and CXCR4 association and cAMP/NF-kappaB effects"}],"covers":["LR005010"]},"LR003300":{"pair":"SFTPD -> SIRPB1","headline":"SP-D binds the D3 domain of SIRPbeta in one abstract-level paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"Direction and effect are not reported in our evidence; the paper reports specific binding to the membrane-proximal D3 domain of SIRPbeta [PMID:22511785].","molecular_requirements":"Domain-deletion mutants localised binding to the D3 domain [PMID:22511785].","affinity_potency":[],"species_and_systems":"Domain-deletion mutant binding assay; species and system details are not reported in our evidence in the dossier.","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no functional readout for SIRPB1.","key_references":[{"PMID":"22511785","why":"SP-D binding to SIRPbeta D3 domain"}],"covers":["LR003300"]},"LR001401":{"pair":"SPINK1 -> EGFR","headline":"SPINK1 binds EGFR and weakly activates it in prostate cancer models; one paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Recombinant SPINK1 induced EGFR phosphorylation in 22RV1 cells, weaker than EGF; EGFR knockdown or cetuximab reduced SPINK1 effects, so SPINK1 partially mediates neoplastic effects through EGFR [PMID:21368222]. Partial agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human: SPINK1-GST pulled down EGFR from EGFR-overexpressing HEK293 lysates and from endogenous EGFR in 22RV1 cells; endogenous SPINK1-EGFR co-immunoprecipitation was not detected [PMID:21368222]. Xenografts in mice. Mouse pair ortholog-inferred.","localisation_and_range":"SPINK1 is flagged secreted [flag]; acts on cell-surface EGFR.","caveats":"Only some, not all, SPINK1 effects are EGFR-dependent [PMID:21368222]. One further paper was review_only. No affinity.","key_references":[{"PMID":"21368222","why":"SPINK1 interacts with EGFR and induces its phosphorylation"}],"covers":["LR001401","LR004796"]},"LR002004":{"pair":"SPON1 -> APP","headline":"F-spondin binds the extracellular domain of APP and inhibits its beta-secretase cleavage; one abstract-level paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"F-spondin binds the conserved central extracellular domain of APP and inhibits beta-secretase cleavage of APP [PMID:14983046]. Effect: antagonist-like on processing; presented as the first functionally active extracellular APP ligand.","molecular_requirements":"Binds the central extracellular domain of APP [PMID:14983046].","affinity_potency":[],"species_and_systems":"Human proteins per curator record; IntAct pull-down records cite this paper [DB:IntAct]. Mouse pair ortholog-inferred.","localisation_and_range":"F-spondin is secreted and APP is a membrane protein [flag]; acts at the cell surface.","caveats":"Abstract only; no affinity; APP is more a precursor than a classical signalling receptor.","key_references":[{"PMID":"14983046","why":"F-spondin binds APP extracellular domain, inhibits beta-secretase cleavage"}],"covers":["LR002004","LR005332"]},"LR001410":{"pair":"SST -> SSTR1","headline":"Somatostatin binds SSTR1 with high affinity in recombinant cells; well supported by several binding papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist: SSTR1 shows specific somatostatin binding, apparently higher for somatostatin-14 than somatostatin-28 [PMID:1346068]; GtoPdb gives pKi 8.6-9.5 [DB:GtoPdb].","molecular_requirements":"SSTR1 alone is sufficient in transfected cells [PMID:1346068]. SSTR1 belongs to a pharmacological subclass (with hsstr4) reacting poorly with synthetic hexapeptide and octapeptide analogs [PMID:7988476].","affinity_potency":[{"value":"pKi 8.6-9.5","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:7988476"}],"species_and_systems":"Human SSTR1 stably expressed in CHO or CCL39 cells [PMID:1346068][PMID:9650799][PMID:7988476]; mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag]; receptor transmembrane.","caveats":"All abstract-only. PMID:9650799 uses a somatostatin-28 analogue radioligand as control, and PMID:7988476 mainly compares analogs. Four pending, two review-only and one abstract-insufficient rows are not counted.","key_references":[{"PMID":"1346068","why":"Cloning of SSTR1; specific somatostatin binding"},{"PMID":"9650799","why":"Five human SSTRs, SRIF28 analogue control"},{"PMID":"7988476","why":"Cross-subtype analog binding"}],"covers":["LR001410","LR004805"]},"LR002013":{"pair":"ST6GAL1 -> CD22","headline":"CD22 binds cell-surface ST6GAL1 (CD75) on activated B cells, shown by a single 1991 abstract-level study.","interaction_type":"direct binding","direction_and_effect":"CD22 recognises CD75, a cell-surface alpha 2-6 sialyltransferase, as a second ligand, expressed mainly on activated B cells [PMID:1717156]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence. The CD22 beta polypeptide was the form that interacted with CD45RO on CD4+ T cells in the same study [PMID:1717156].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:1717156]. The mouse entry is projected from human evidence.","localisation_and_range":"ST6GAL1 is flagged secreted [flag], but the paper describes it as a cell-surface enzyme on B cells, so contact (juxtacrine) signalling is suggested [PMID:1717156].","caveats":"One paper read as abstract only; the second confirmed row is not shown. The ligand is an enzyme recognised via its CD75 glycan identity; whether protein or glycan epitope is bound is not stated. No databases support the pair.","key_references":[{"PMID":"1717156","why":"CD22 recognises CD75 (alpha 2-6 sialyltransferase) on activated B cells"}],"covers":["LR002013","LR005341"]},"LR011013":{"pair":"THBS1 -> TGFB1","headline":"Ligand-ligand physical association (co-purification, solid-phase assay) in databases; no curated papers support a receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID reports TGFB1 and THBS1 co-purification and IntAct reports a solid-phase assay [DB:BioGRID, DB:IntAct]. This is a ligand-ligand interaction, not a signalling pair; direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; database records cite PMIDs 1550960 and 15864306 [DB:BioGRID, DB:IntAct].","localisation_and_range":"Both partners are flagged secreted [flag].","caveats":"Curated papers judged were different_entity (6) or abstract_insufficient (1), none confirming. TGFB1 is not a receptor here; the entry reflects binding or latent-complex regulation only if the databases are right.","key_references":[],"covers":["LR011013"]},"LR002022":{"pair":"TNC -> ITGB3","headline":"Beta3 (alphavbeta3) binds tenascin-C: C-terminal fibrinogen-like domain binding and SMC functional data; abstract-only.","interaction_type":"direct binding","direction_and_effect":"The tenascin C C-terminal fibrinogen-like domain specifically binds alpha(v)beta(3), as does a peptide derived from it [PMID:10747940]. Affinity purification identified alphavbeta3 as a tenascin-binding receptor on endothelial cells [PMID:7693733]. TN-C/alphavbeta3 interaction promotes EGF-dependent SMC growth [PMID:9314546].","molecular_requirements":"Partner alphaV chain is needed [PMID:10747940]; binding via the SRRGDMS site in one paper [PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells per curator records; HUVEC [PMID:7693733], SMC [PMID:9314546].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"All abstract-only. Single-chain entry. Two further rows abstract_insufficient.","key_references":[{"PMID":"10747940","why":"TNC fibrinogen-like domain binds alphavbeta3"},{"PMID":"7693733","why":"alphavbeta3 identified as tenascin receptor"},{"PMID":"9314546","why":"alphavbeta3 and EGF-R in SMCs"}],"covers":["LR002022","LR005350"]},"LR001500":{"pair":"TNFSF13B -> TNFRSF17","headline":"BAFF binds BCMA, supported by three abstract-only binding papers and database records.","interaction_type":"direct binding","direction_and_effect":"BCMA specifically binds TALL-1 (BAFF); soluble BCMA blocks TALL-1 binding and B-cell costimulation, and BCMA overexpression activates NF-kappaB, potentiated by TALL-1 [PMID:10908663]. TACI and BCMA bind zTNF4 [PMID:10801128]. Annotated stimulatory [flag].","molecular_requirements":"BCMA signalling to NF-kappaB depends on TRAF5, TRAF6, NIK and IKK in dominant-negative experiments [PMID:10908663]. Reactome lists a complex with TACI and BCMA [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:10908663]; TACI-Ig in lupus mice (TACI, not BCMA) [PMID:10801128].","localisation_and_range":"BAFF flagged secreted and transmembrane; BCMA transmembrane [flag].","caveats":"Papers are abstract only; BAFF affinity for BCMA is much weaker than APRIL's, per a paper listed under a different pair, so not shown here. One paper reports APRIL competes with TALL-I for BCMA binding [PMID:10973284].","key_references":[{"PMID":"10908663","why":"BCMA binds TALL-1 and activates NF-kappaB"},{"PMID":"10801128","why":"TACI and BCMA identified as BAFF receptors"},{"PMID":"10973284","why":"APRIL and TALL-I compete for BCMA/TACI"}],"covers":["LR001500","LR004891"]},"LR004899":{"pair":"TNFSF18 -> TNFRSF18","headline":"GITRL-GITR is supported by two abstract-only functional papers and structures.","interaction_type":"functional only","direction_and_effect":"The ligand for AITR was found to be an undescribed TNF family member expressed in endothelial cells [PMID:10037686]. Cotransfection of hGITRL and hGITR in HEK293 cells activated NF-kappaB and inhibited antigen-receptor-induced death in Jurkat [PMID:10074428].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 and Jurkat cells [PMID:10074428].","localisation_and_range":"TNFSF18 flagged transmembrane, not secreted; TNFRSF18 transmembrane [flag].","caveats":"Abstracts only; functional co-transfection, not a binding measurement. SPR in IntAct and PDB structures exist [DB:IntAct][DB:PDB 7KHD].","key_references":[{"PMID":"10074428","why":"NF-kappaB activation by GITRL-GITR"},{"PMID":"10037686","why":"Identification of AITRL"}],"covers":["LR001509","LR004899"]},"LR011130":{"pair":"UBC -> SMAD3","headline":"Database-asserted only: a single IntAct co-immunoprecipitation record between ubiquitin precursor and SMAD3; no ligand-receptor paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no paper in the dossier shows a signalling direction or effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The only support is an IntAct record (anti tag coimmunoprecipitation) [DB:IntAct] [PMID:22045334]; experimental species and system are not reported in our evidence.","localisation_and_range":"Not reported in our evidence; no entity annotation flags are given for either partner.","caveats":"Rests on one database record alone. Curators judged 3 papers as concerning a different entity, so none supports this pair. A co-immunoprecipitation does not show ligand-receptor signalling.","key_references":[],"covers":["LR011130"]},"LR011400":{"pair":"VTN -> ITGAV:ITGB1","headline":"No paper supports the alphaV:beta1 complex for vitronectin; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. IntAct lists a solid phase assay [DB:IntAct] and Reactome lists vitronectin binding to alphaVbeta3, alphaVbeta5 and alphaVbeta8 in the examples shown [DB:Reactome].","molecular_requirements":"Two-chain complex ITGAV with ITGB1 [flag]; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human entity labels.","localisation_and_range":"Vitronectin is flagged as secreted [flag].","caveats":"No verified papers; 1 abstract was insufficient. The records shown do not name alphaVbeta1 specifically [DB:Reactome] [DB:IntAct].","key_references":[],"covers":["LR011400"]},"LR002031":{"pair":"WNT1 -> FZD2","headline":"WNT1 signals through FZD2 in HEK293T knockout-rescue reporter experiments; functional, not direct binding.","interaction_type":"functional only","direction_and_effect":"Expressing FZD2 or FZD7 each rescued Wnt3- and Wnt1-dependent TCF4/Wnt reporter activity in FZD1/2/7 multiplex-CRISPR knockout cells [PMID:28733458].","molecular_requirements":"FZD2 alone sufficed in the rescue; FZD7 could substitute, so paralogs are redundant [PMID:28733458]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293T cells with CRISPR FZD knockouts; the mouse pair is ortholog-inferred [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Loss-of-function plus rescue supports receptor use but not physical binding. FZD7 is an alternative receptor in this system.","key_references":[{"PMID":"28733458","why":"Knockout-rescue map of Wnt-FZD functional pairs"}],"covers":["LR002031","LR005357"]},"LR002040":{"pair":"WNT2 -> FZD2","headline":"WNT2 interacts with FZD2 by co-IP and drives STAT3-dependent invasion in oesophageal cancer cells.","interaction_type":"direct binding","direction_and_effect":"WNT2 and FZD2 interacted (co-IP); WNT2 protein (50 ng/mL) increased FZD2, reduced FZD2 ubiquitination, and activated STAT3, with migration and invasion attenuated by FZD2 knockdown (agonist annotated) [PMID:32766155].","molecular_requirements":"FZD2 knockdown blunted the WNT2 response; no co-receptor requirement reported [PMID:32766155].","affinity_potency":[],"species_and_systems":"Human ESCC cell lines (KYSE30, KYSE150), plus xenograft work in the paper [PMID:32766155].","localisation_and_range":"WNT2 flagged secreted; CAF-secreted WNT2 acts on cancer cells [PMID:32766155]. Mouse pair is ortholog-inferred.","caveats":"Mechanism is non-canonical STAT3, not beta-catenin. No affinity. Co-IP is in overexpression or lysates; domain not reported.","key_references":[{"PMID":"32766155","why":"WNT2-FZD2 interaction and FZD2/STAT3 signalling in ESCC"}],"covers":["LR002040","LR005366"]},"LR006699":{"pair":"WNT4 -> FZD5","headline":"WNT4 binds FZD5 in purified protein and co-IP assays but does not activate canonical beta-catenin signalling through it.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 directly binds the FZD5 cysteine-rich domain, but in 32D cells WNT-4 did not activate the WNT-beta-catenin pathway through it; effects on DVL2 vs DVL3 phosphorylation suggest non-canonical output [PMID:25605717].","molecular_requirements":"The CRD of the Frizzled is sufficient for binding in the assay [PMID:25605717].","affinity_potency":[],"species_and_systems":"Bio-layer interferometry and 32D cells, human labelled [PMID:25605717]. Mouse version listed directly; human is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; affinity values are in a table not shown in our evidence. Curator effect label 'agonist' conflicts with the non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"WNT-FZD CRD binding kinetics and signalling"}],"covers":["LR003499","LR006699"]},"LR004989":{"pair":"WNT4 -> FZD6","headline":"Several papers support WNT4-FZD6 binding and function, but FZD6 does not carry the canonical signal.","interaction_type":"direct binding","direction_and_effect":"Wnt-4 forms a biochemical complex with the Frizzled-6 CRD in MDCK cells [PMID:15265686]. Fz6 is needed for Wnt4-mediated expansion of mouse fetal liver LSKs, with Rac1/Jnk rather than beta-catenin output [PMID:21541287]. Wnt-4 changes FZD6-GFP mobility in HEK293T/17 cells [PMID:24873871]. Effect is agonist [DB:GtoPdb].","molecular_requirements":"FZD6 CRD suffices for the complex [PMID:15265686]; Wnt4-Fzd6 co-IP also seen [PMID:31216173].","affinity_potency":[],"species_and_systems":"MDCK (canine) [PMID:15265686]; mouse fetal liver [PMID:21541287]; HEK293T/17 human FZD6 [PMID:24873871]; MC3T3 mouse [PMID:31216173].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Frizzled-6 does not appear to transduce Wnt-4's canonical signal in MDCK cells [PMID:15265686]. FRAP shows receptor-level action only [PMID:24873871]. Two papers read as abstract or browser, one unchecked. No affinity in our evidence.","key_references":[{"PMID":"15265686","why":"Wnt-4 complex with Fz6 CRD"},{"PMID":"21541287","why":"Fz6 needed for Wnt4 effect in fetal liver LSKs"},{"PMID":"24873871","why":"WNT-4 alters FZD6 mobility"}],"covers":["LR001600","LR004989"]},"LR007689":{"pair":"WNT5A -> FZD7:LRP6","headline":"Database-asserted only: BioGRID, IntAct and Reactome records; no curator-verified paper for this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. Reactome lists a WNT5A:FZD7 complex and WNT5 binding FZD7 [DB:Reactome R-HSA-9673349].","molecular_requirements":"BioGRID records LRP6-WNT5A by affinity capture-Western [DB:BioGRID 692083]; IntAct records WNT5A-LRP5 interactions [DB:IntAct O75084-P41221]. A ternary FZD7:LRP6 complex is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Experimental systems not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, LRP6 transmembrane [flag].","caveats":"No verified papers (one review-only row). Subunit pairing is inferred from separate binary records, not from a ternary complex assay.","key_references":[],"covers":["LR007689"]},"LR004998":{"pair":"WNT5A -> MCAM","headline":"CD146 (MCAM) is reported to bind Wnt5a with high affinity and to signal through Dvl/JNK; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD146 binds Wnt5a with high affinity, required for Wnt5a-induced Dvl and JNK activation, promoting cell migration; CD146 also inhibits canonical Wnt signalling by promoting beta-catenin degradation [PMID:24335906]. Curated agonist.","molecular_requirements":"The Dvl2-binding region of CD146 is needed for JNK activation and migration [PMID:24335906]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell migration assays and zebrafish convergent extension [PMID:24335906].","localisation_and_range":"MCAM is flagged non-secreted and non-transmembrane, which looks inconsistent with a cell-surface receptor [flag]; ligand flagged secreted [flag].","caveats":"Abstract only; the 'high affinity' value is not given in our evidence.","key_references":[{"PMID":"24335906","why":"CD146 as a high-affinity Wnt5a receptor"}],"covers":["LR001609","LR004998"]},"LR005001":{"pair":"WNT5A -> RYK","headline":"RYK mediates WNT5A effects in several functional studies; one study measured weak binding and found RYK is not a co-receptor of FZD5.","interaction_type":"functional only","direction_and_effect":"RYK knockdown reversed WNT5A-induced apoptosis in prostate cancer cells [PMID:29930766]; WNT5A signalling in rheumatoid synoviocytes required RYK, via WNT/Ca2+ [PMID:33178184]; Wnt5a acts as a chemorepulsive ligand for Ryk in mouse callosal axons [PMID:16723543]. Curated stimulatory.","molecular_requirements":"RYK acted as a single receptor; sequential binding showed RYK does not act as a co-receptor for FZD5 and WNT5A binds FZD5 or RYK at the same site [PMID:29930766].","affinity_potency":[],"species_and_systems":"Human PC3 cells and rheumatoid synoviocytes; Ryk-deficient mice for axon guidance [PMID:16723543].","localisation_and_range":"Membrane receptor; Reactome lists WNT5A:RYK:VANGL2 [DB:Reactome R-HSA-4551548].","caveats":"Binding in the surface assay needed high concentrations, and WNT5A binding to FZD5 was 31% higher than to RYK [PMID:29930766]. Effect direction is mixed: agonist in cells, antagonist label for axon guidance; two papers are abstract-only.","key_references":[{"PMID":"29930766","why":"RYK knockdown and binding data in prostate cancer cells"},{"PMID":"33178184","why":"RYK required for WNT5A in synoviocytes"},{"PMID":"16723543","why":"Ryk and Wnt5a axon guidance in mouse"}],"covers":["LR001612","LR005001"]}};